  "DocumentNumber" varchar(100) NULL,
  "IssueDate" date NULL,
  "IssueDateHijriText" varchar(20) NULL,
  "ExpiryDate" date NULL,
  "ExpiryDateHijriText" varchar(20) NULL,
  "IssuingAuthority" varchar(200) NULL,
