CREATE TABLE "org"."CompanyTaxRate" (
  "TenantId" integer NOT NULL,
  "CompanyTaxRateId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CompanyId" bigint NULL,
  "TaxCode" varchar(20) NOT NULL,
  "RatePercent" numeric(9,6) NOT NULL,
  "EffectiveFrom" date NOT NULL,
  "EffectiveTo" date NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CompanyTaxRateId"),
  CONSTRAINT "UQ_CompanyTaxRate_Tenant" UNIQUE ("TenantId", "CompanyTaxRateId"),
  CONSTRAINT "UQ_CompanyTaxRate_CompanyId_TaxCode_EffectiveFrom" UNIQUE ("TenantId", "CompanyId", "TaxCode", "EffectiveFrom"),
  CONSTRAINT "CK_CompanyTaxRate_1" CHECK ("RatePercent" >= 0 AND "RatePercent" <= 100),
  CONSTRAINT "CK_CompanyTaxRate_2" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom")
);
CREATE TABLE "org"."Department" (
  "TenantId" integer NOT NULL,
  "DepartmentId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Code" varchar(20) NOT NULL,
  "NameAr" varchar(200) NOT NULL,
  "NameEn" varchar(200) NOT NULL,
  "Function" varchar(11) NOT NULL,
  "IsTreasury" smallint NOT NULL DEFAULT 0,
  CHECK ("IsTreasury" IS NULL OR "IsTreasury" IN (0,1)),
  "CompanyId" bigint NULL,
  "ParentDepartmentId" bigint NULL,
  "HeadUserId" bigint NULL,
  "IsActive" smallint NOT NULL DEFAULT 1,
  CHECK ("IsActive" IS NULL OR "IsActive" IN (0,1)),
  "SeedKey" varchar(80) NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("DepartmentId"),
  CONSTRAINT "UQ_Department_Tenant" UNIQUE ("TenantId", "DepartmentId"),
  CONSTRAINT "UQ_Department_Code" UNIQUE ("TenantId", "Code"),
  CONSTRAINT "CK_Department_1" CHECK ("ParentDepartmentId" IS NULL OR "ParentDepartmentId" <> "DepartmentId"),
  CONSTRAINT "CK_Department_Function" CHECK ("Function" IS NULL OR "Function" IN ('PROCUREMENT', 'SALES', 'TREASURY', 'FINANCE', 'OTHER'))
);
CREATE TABLE "org"."Shareholding" (
  "TenantId" integer NOT NULL,
  "ShareholdingId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CompanyId" bigint NOT NULL,
  "HolderPartyId" bigint NOT NULL,
  "SharePercent" numeric(9,6) NOT NULL,
  "SharesCount" numeric(19,4) NULL,
  "NominalValue" numeric(19,4) NULL,
  "CurrencyId" integer NULL,
  "Layer" smallint NOT NULL DEFAULT 1,
  "IsBeneficialOwner" smallint NOT NULL DEFAULT 0,
  CHECK ("IsBeneficialOwner" IS NULL OR "IsBeneficialOwner" IN (0,1)),
  "EffectiveFrom" date NOT NULL,
  "EffectiveTo" date NULL,
  "SourceDocumentId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("ShareholdingId"),
  CONSTRAINT "UQ_Shareholding_Tenant" UNIQUE ("TenantId", "ShareholdingId"),
  CONSTRAINT "UQ_Shareholding_CompanyId_HolderPartyId_Layer_EffectiveFrom" UNIQUE ("TenantId", "CompanyId", "HolderPartyId", "Layer", "EffectiveFrom"),
  CONSTRAINT "CK_Shareholding_1" CHECK ("SharePercent" > 0 AND "SharePercent" <= 100),
  CONSTRAINT "CK_Shareholding_2" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom"),
  CONSTRAINT "CK_Shareholding_3" CHECK ("Layer" >= 1),
  CONSTRAINT "CK_Shareholding_4" CHECK ("SharesCount" IS NULL OR "SharesCount" > 0),
  CONSTRAINT "CK_Shareholding_5" CHECK ("NominalValue" IS NULL OR ("NominalValue" >= 0 AND "CurrencyId" IS NOT NULL))
);
CREATE TABLE "org"."GoverningBody" (
  "TenantId" integer NOT NULL,
  "GoverningBodyId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CompanyId" bigint NOT NULL,
  "BodyType" varchar(18) NOT NULL,
  "NameAr" varchar(200) NULL,
  "NameEn" varchar(200) NULL,
  "TermStart" date NULL,
  "TermEnd" date NULL,
  "QuorumRuleText" text NULL,
  "DecisionRuleText" text NULL,
  "Status" varchar(10) NOT NULL DEFAULT 'ACTIVE',
  "SourceDocumentId" bigint NULL,
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("GoverningBodyId"),
  CONSTRAINT "UQ_GoverningBody_Tenant" UNIQUE ("TenantId", "GoverningBodyId"),
  CONSTRAINT "UQ_GoverningBody_Scope_CompanyId" UNIQUE ("TenantId", "CompanyId", "GoverningBodyId"),
  CONSTRAINT "UQ_GoverningBody_PublicId" UNIQUE ("PublicId"),
  CONSTRAINT "CK_GoverningBody_1" CHECK ("TermEnd" IS NULL OR "TermStart" IS NULL OR "TermEnd" >= "TermStart"),
  CONSTRAINT "CK_GoverningBody_BodyType" CHECK ("BodyType" IS NULL OR "BodyType" IN ('BOARD_OF_DIRECTORS', 'BOARD_OF_MANAGERS', 'MANAGEMENT', 'GENERAL_ASSEMBLY')),
  CONSTRAINT "CK_GoverningBody_Status" CHECK ("Status" IS NULL OR "Status" IN ('ACTIVE', 'CLOSED'))
);
CREATE TABLE "org"."BodyMember" (
  "TenantId" integer NOT NULL,
  "BodyMemberId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CompanyId" bigint NOT NULL,
  "BodyId" bigint NOT NULL,
  "PartyId" bigint NOT NULL,
  "PositionId" integer NOT NULL,
  "TermStart" date NOT NULL,
  "TermEnd" date NULL,
  "RepresentedPartyId" bigint NULL,
  "ResignedOn" date NULL,
  "AppointmentDocumentId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("BodyMemberId"),
  CONSTRAINT "UQ_BodyMember_Tenant" UNIQUE ("TenantId", "BodyMemberId"),
  CONSTRAINT "UQ_BodyMember_Scope_CompanyId" UNIQUE ("TenantId", "CompanyId", "BodyMemberId"),
  CONSTRAINT "UQ_BodyMember_BodyId_PartyId_PositionId_TermStart" UNIQUE ("TenantId", "BodyId", "PartyId", "PositionId", "TermStart"),
  CONSTRAINT "CK_BodyMember_1" CHECK ("TermEnd" IS NULL OR "TermEnd" >= "TermStart"),
  CONSTRAINT "CK_BodyMember_2" CHECK ("ResignedOn" IS NULL OR "ResignedOn" >= "TermStart"),
  CONSTRAINT "CK_BodyMember_3" CHECK ("RepresentedPartyId" IS NULL OR "RepresentedPartyId" <> "PartyId")
);
CREATE TABLE "org"."AuthorityGrant" (
  "TenantId" integer NOT NULL,
  "AuthorityGrantId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CompanyId" bigint NOT NULL,
  "GranteeKind" varchar(11) NOT NULL,
  "BodyId" bigint NULL,
  "BodyMemberId" bigint NULL,
  "PartyId" bigint NULL,
  "PowerTypeId" integer NOT NULL,
  "InstitutionId" bigint NULL,
  "CeilingAmount" numeric(19,4) NULL,
  "CeilingCurrencyId" integer NULL,
  "RequiresJoint" smallint NOT NULL DEFAULT 0,
  CHECK ("RequiresJoint" IS NULL OR "RequiresJoint" IN (0,1)),
  "JointMinSignatories" integer NULL,
  "JointNote" text NULL,
  "ValidFrom" date NOT NULL,
  "ValidFromHijriText" varchar(20) NULL,
  "ValidTo" date NULL,
  "Status" varchar(16) NOT NULL DEFAULT 'DRAFT',
  "ApprovedBy" bigint NULL,
  "ApprovedAt" timestamp(3) NULL,
  "RevokedAt" timestamp(3) NULL,
  "RevokedReason" text NULL,
  "SourceDocumentId" bigint NULL,
  "SourcePage" varchar(40) NULL,
  "ExceptionReason" varchar(500) NULL,
  "SupersedesGrantId" bigint NULL,
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("AuthorityGrantId"),
  CONSTRAINT "UQ_AuthorityGrant_Tenant" UNIQUE ("TenantId", "AuthorityGrantId"),
  CONSTRAINT "UQ_AuthorityGrant_PublicId" UNIQUE ("PublicId"),
  CONSTRAINT "CK_AuthorityGrant_1" CHECK (("GranteeKind" = 'BODY' AND "BodyId" IS NOT NULL AND "BodyMemberId" IS NULL AND "PartyId" IS NULL) OR ("GranteeKind" = 'BODY_MEMBER' AND "BodyId" IS NULL AND "BodyMemberId" IS NOT NULL AND "PartyId" IS NULL) OR ("GranteeKind" = 'PARTY' AND "BodyId" IS NULL AND "BodyMemberId" IS NULL AND "PartyId" IS NOT NULL)),
  CONSTRAINT "CK_AuthorityGrant_2" CHECK ("CeilingAmount" IS NULL OR "CeilingAmount" > 0),
  CONSTRAINT "CK_AuthorityGrant_3" CHECK (("CeilingAmount" IS NULL AND "CeilingCurrencyId" IS NULL) OR ("CeilingAmount" IS NOT NULL AND "CeilingCurrencyId" IS NOT NULL)),
  CONSTRAINT "CK_AuthorityGrant_4" CHECK (("RequiresJoint" = 1 AND "JointMinSignatories" IS NOT NULL AND "JointMinSignatories" >= 2) OR ("RequiresJoint" = 0 AND "JointMinSignatories" IS NULL)),
  CONSTRAINT "CK_AuthorityGrant_5" CHECK ("ValidTo" IS NULL OR "ValidTo" >= "ValidFrom"),
  CONSTRAINT "CK_AuthorityGrant_6" CHECK ("Status" IN ('DRAFT','PENDING_APPROVAL') OR "SourceDocumentId" IS NOT NULL OR "ExceptionReason" IS NOT NULL),
  CONSTRAINT "CK_AuthorityGrant_7" CHECK ("Status" <> 'REVOKED' OR ("RevokedAt" IS NOT NULL AND "RevokedReason" IS NOT NULL)),
  CONSTRAINT "CK_AuthorityGrant_8" CHECK ("SupersedesGrantId" IS NULL OR "SupersedesGrantId" <> "AuthorityGrantId"),
  CONSTRAINT "CK_AuthorityGrant_GranteeKind" CHECK ("GranteeKind" IS NULL OR "GranteeKind" IN ('BODY', 'BODY_MEMBER', 'PARTY')),
  CONSTRAINT "CK_AuthorityGrant_Status" CHECK ("Status" IS NULL OR "Status" IN ('DRAFT', 'PENDING_APPROVAL', 'ACTIVE', 'SUPERSEDED', 'REVOKED'))
);
CREATE TABLE "org"."CompanyProfile" (
  "TenantId" integer NOT NULL,
  "CompanyProfileId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CompanyId" bigint NOT NULL,
  "UnifiedNationalNo" varchar(20) NULL,
  "ForeignInvestmentLicenseNo" varchar(40) NULL,
  "ForeignInvestmentLicenseIssuedOn" date NULL,
  "ForeignInvestmentLicenseExpiresOn" date NULL,
  "GovernmentEntityId" varchar(40) NULL,
  "Lei" varchar(20) NULL,
  "HeadquartersCountryId" integer NULL,
  "EntityKind" varchar(19) NULL,
  "NationalityClass" varchar(10) NULL,
  "SectorId" integer NULL,
  "PrimaryActivityText" varchar(300) NULL,
  "ActivityNature" varchar(300) NULL,
  "ActivityDescription" text NULL,
  "EmployeeBandId" integer NULL,
  "DeclaredBranchCount" integer NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CompanyProfileId"),
  CONSTRAINT "UQ_CompanyProfile_Tenant" UNIQUE ("TenantId", "CompanyProfileId"),
  CONSTRAINT "UQ_CompanyProfile_CompanyId" UNIQUE ("TenantId", "CompanyId"),
  CONSTRAINT "CK_CompanyProfile_1" CHECK ("Lei" IS NULL OR "Lei" LIKE '____________________'),
  CONSTRAINT "CK_CompanyProfile_2" CHECK ("ForeignInvestmentLicenseExpiresOn" IS NULL OR "ForeignInvestmentLicenseIssuedOn" IS NULL OR "ForeignInvestmentLicenseExpiresOn" > "ForeignInvestmentLicenseIssuedOn"),
  CONSTRAINT "CK_CompanyProfile_3" CHECK ("DeclaredBranchCount" IS NULL OR "DeclaredBranchCount" >= 0),
  CONSTRAINT "CK_CompanyProfile_EntityKind" CHECK ("EntityKind" IS NULL OR "EntityKind" IN ('COMPANY', 'SOLE_PROPRIETORSHIP', 'GOVERNMENT', 'OTHER')),
  CONSTRAINT "CK_CompanyProfile_NationalityClass" CHECK ("NationalityClass" IS NULL OR "NationalityClass" IN ('DOMESTIC', 'GCC', 'OTHER'))
);
CREATE TABLE "org"."CompanyBranch" (
  "TenantId" integer NOT NULL,
  "CompanyBranchId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CompanyId" bigint NOT NULL,
  "BranchKind" varchar(19) NOT NULL DEFAULT 'BRANCH',
  "NameAr" varchar(200) NULL,
  "NameEn" varchar(200) NULL,
  "CountryId" integer NULL,
  "LocationText" varchar(300) NULL,
  "CrNumber" varchar(30) NULL,
  "UnifiedNationalNo" varchar(20) NULL,
  "ActivityText" varchar(300) NULL,
  "OwnershipPercent" numeric(9,6) NULL,
  "Status" varchar(10) NOT NULL DEFAULT 'ACTIVE',
  "ClosedOn" date NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CompanyBranchId"),
  CONSTRAINT "UQ_CompanyBranch_Tenant" UNIQUE ("TenantId", "CompanyBranchId"),
  CONSTRAINT "CK_CompanyBranch_1" CHECK ("NameAr" IS NOT NULL OR "NameEn" IS NOT NULL),
  CONSTRAINT "CK_CompanyBranch_2" CHECK ("OwnershipPercent" IS NULL OR ("BranchKind" = 'EXTERNAL_SUBSIDIARY' AND "OwnershipPercent" > 0 AND "OwnershipPercent" <= 100)),
  CONSTRAINT "CK_CompanyBranch_3" CHECK ("ClosedOn" IS NULL OR "Status" = 'CLOSED'),
  CONSTRAINT "CK_CompanyBranch_BranchKind" CHECK ("BranchKind" IS NULL OR "BranchKind" IN ('BRANCH', 'WAREHOUSE', 'EXTERNAL_SUBSIDIARY')),
  CONSTRAINT "CK_CompanyBranch_Status" CHECK ("Status" IS NULL OR "Status" IN ('ACTIVE', 'CLOSED'))
);
CREATE TABLE "org"."CompanyKycFinancialProfile" (
  "TenantId" integer NOT NULL,
  "CompanyKycFinancialProfileId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CompanyId" bigint NOT NULL,
  "EffectiveFrom" date NOT NULL,
  "EffectiveTo" date NULL,
  "RevenueBandId" integer NULL,
  "AccountPurposeText" varchar(500) NULL,
  "AccountCurrencyId" integer NULL,
  "PreferredLanguage" varchar(10) NULL,
  "FundsTransferSource" varchar(300) NULL,
  "RequestedServices" varchar(300) NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CompanyKycFinancialProfileId"),
  CONSTRAINT "UQ_CompanyKycFinancialProfile_Tenant" UNIQUE ("TenantId", "CompanyKycFinancialProfileId"),
  CONSTRAINT "UQ_CompanyKycFinancialProfile_CompanyId_EffectiveFrom" UNIQUE ("TenantId", "CompanyId", "EffectiveFrom"),
  CONSTRAINT "CK_CompanyKycFinancialProfile_1" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom"),
  CONSTRAINT "CK_CompanyKycFinancialProfile_PreferredLanguage" CHECK ("PreferredLanguage" IS NULL OR "PreferredLanguage" IN ('ar', 'en'))
);
CREATE TABLE "org"."CompanyExpectedFlow" (
  "TenantId" integer NOT NULL,
  "CompanyExpectedFlowId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "FinancialProfileId" bigint NOT NULL,
  "Direction" varchar(10) NOT NULL,
  "FlowKind" varchar(22) NOT NULL,
  "MonthlyAmount" numeric(19,4) NOT NULL,
  "CurrencyId" integer NOT NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CompanyExpectedFlowId"),
  CONSTRAINT "UQ_CompanyExpectedFlow_Tenant" UNIQUE ("TenantId", "CompanyExpectedFlowId"),
  CONSTRAINT "UQ_CompanyExpectedFlow_FinancialProfileId_Direction_FlowKind" UNIQUE ("TenantId", "FinancialProfileId", "Direction", "FlowKind"),
  CONSTRAINT "CK_CompanyExpectedFlow_1" CHECK ("MonthlyAmount" >= 0),
  CONSTRAINT "CK_CompanyExpectedFlow_Direction" CHECK ("Direction" IS NULL OR "Direction" IN ('DEPOSIT', 'WITHDRAWAL')),
  CONSTRAINT "CK_CompanyExpectedFlow_FlowKind" CHECK ("FlowKind" IS NULL OR "FlowKind" IN ('CASH', 'OTHER', 'LOCAL_TRANSFER', 'INTERNATIONAL_TRANSFER', 'CHEQUE'))
);
CREATE TABLE "org"."CompanyWealthSource" (
  "TenantId" integer NOT NULL,
  "FinancialProfileId" bigint NOT NULL,
  "WealthSourceId" integer NOT NULL,
  "OtherText" varchar(200) NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("TenantId", "FinancialProfileId", "WealthSourceId")
);
CREATE TABLE "org"."CompanyDisclosure" (
  "TenantId" integer NOT NULL,
  "CompanyDisclosureId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CompanyId" bigint NOT NULL,
  "DisclosureKind" varchar(23) NOT NULL,
  "Description" text NOT NULL,
  "EventDate" date NULL,
  "Status" varchar(10) NOT NULL DEFAULT 'OPEN',
  "ResolvedOn" date NULL,
  "SourceDocumentId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CompanyDisclosureId"),
  CONSTRAINT "UQ_CompanyDisclosure_Tenant" UNIQUE ("TenantId", "CompanyDisclosureId"),
  CONSTRAINT "CK_CompanyDisclosure_1" CHECK ("ResolvedOn" IS NULL OR "Status" = 'RESOLVED'),
  CONSTRAINT "CK_CompanyDisclosure_DisclosureKind" CHECK ("DisclosureKind" IS NULL OR "DisclosureKind" IN ('REGULATORY_DISCIPLINARY', 'TAX_ISSUE', 'LITIGATION', 'FACILITY_RESCHEDULING', 'CONVICTION', 'OTHER')),
  CONSTRAINT "CK_CompanyDisclosure_Status" CHECK ("Status" IS NULL OR "Status" IN ('OPEN', 'RESOLVED'))
);
CREATE TABLE "org"."CompanyKeyRelation" (
  "TenantId" integer NOT NULL,
  "CompanyKeyRelationId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CompanyId" bigint NOT NULL,
  "RelationKind" varchar(14) NOT NULL,
  "NameAr" varchar(200) NULL,
  "NameEn" varchar(200) NULL,
  "Note" varchar(500) NULL,
  "IsActive" smallint NOT NULL DEFAULT 1,
  CHECK ("IsActive" IS NULL OR "IsActive" IN (0,1)),
  "SortOrder" integer NOT NULL DEFAULT 0,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CompanyKeyRelationId"),
  CONSTRAINT "UQ_CompanyKeyRelation_Tenant" UNIQUE ("TenantId", "CompanyKeyRelationId"),
  CONSTRAINT "CK_CompanyKeyRelation_1" CHECK ("NameAr" IS NOT NULL OR "NameEn" IS NOT NULL),
  CONSTRAINT "CK_CompanyKeyRelation_RelationKind" CHECK ("RelationKind" IS NULL OR "RelationKind" IN ('AUDITOR', 'ACCOUNTANT', 'LEGAL_ADVISOR', 'REGULATOR', 'MAJOR_CUSTOMER', 'MAJOR_SUPPLIER', 'OTHER'))
);
CREATE TABLE "pty"."Party" (
  "TenantId" integer NOT NULL,
  "PartyId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "PartyCode" varchar(20) NOT NULL,
  "Kind" varchar(12) NOT NULL,
  "NameAr" varchar(200) NULL,
  "NameEn" varchar(200) NULL,
  "NameNormalized" varchar(400) NULL,
  "CountryId" integer NULL,
  "ResidencyStatus" varchar(12) NULL,
  "BirthDate" date NULL,
  "BirthDateHijriText" varchar(20) NULL,
  "BirthPlace" varchar(100) NULL,
  "BirthCountryId" integer NULL,
  "MaritalStatus" varchar(10) NULL,
  "Gender" varchar(10) NULL,
  "EducationLevelId" integer NULL,
  "LinkedCompanyId" bigint NULL,
  "IsActive" smallint NOT NULL DEFAULT 1,
  CHECK ("IsActive" IS NULL OR "IsActive" IN (0,1)),
  "MergedIntoPartyId" bigint NULL,
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("PartyId"),
  CONSTRAINT "UQ_Party_Tenant" UNIQUE ("TenantId", "PartyId"),
  CONSTRAINT "UQ_Party_PublicId" UNIQUE ("PublicId"),
  CONSTRAINT "UQ_Party_PartyCode" UNIQUE ("TenantId", "PartyCode"),
  CONSTRAINT "CK_Party_1" CHECK ("NameAr" IS NOT NULL OR "NameEn" IS NOT NULL),
  CONSTRAINT "CK_Party_2" CHECK ("Kind" = 'INDIVIDUAL' OR ("ResidencyStatus" IS NULL AND "BirthDate" IS NULL AND "MaritalStatus" IS NULL AND "Gender" IS NULL AND "EducationLevelId" IS NULL)),
  CONSTRAINT "CK_Party_3" CHECK ("LinkedCompanyId" IS NULL OR "Kind" = 'ORGANIZATION'),
  CONSTRAINT "CK_Party_4" CHECK ("MergedIntoPartyId" IS NULL OR ("IsActive" = 0 AND "MergedIntoPartyId" <> "PartyId")),
  CONSTRAINT "CK_Party_Kind" CHECK ("Kind" IS NULL OR "Kind" IN ('INDIVIDUAL', 'ORGANIZATION')),
  CONSTRAINT "CK_Party_ResidencyStatus" CHECK ("ResidencyStatus" IS NULL OR "ResidencyStatus" IN ('CITIZEN', 'RESIDENT', 'NON_RESIDENT', 'UNKNOWN')),
  CONSTRAINT "CK_Party_MaritalStatus" CHECK ("MaritalStatus" IS NULL OR "MaritalStatus" IN ('SINGLE', 'MARRIED', 'DIVORCED', 'WIDOWED')),
  CONSTRAINT "CK_Party_Gender" CHECK ("Gender" IS NULL OR "Gender" IN ('MALE', 'FEMALE'))
);
CREATE TABLE "pty"."IdentityDocument" (
  "TenantId" integer NOT NULL,
  "IdentityDocumentId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "PartyId" bigint NOT NULL,
  "DocKind" varchar(14) NOT NULL,
  "IssuingCountryId" integer NOT NULL,
  "IssuingAuthority" varchar(200) NULL,
  "IssuePlace" varchar(100) NULL,
  "NumberEnc" bytea NOT NULL,
  "NumberMask" varchar(32) NOT NULL,
  "NumberHash" bytea NOT NULL,
  "IssueDate" date NULL,
  "IssueDateHijriText" varchar(20) NULL,
  "ExpiryDate" date NULL,
  "ExpiryDateHijriText" varchar(20) NULL,
  "IsPrimary" smallint NOT NULL DEFAULT 0,
  CHECK ("IsPrimary" IS NULL OR "IsPrimary" IN (0,1)),
  "IsSuperseded" smallint NOT NULL DEFAULT 0,
  CHECK ("IsSuperseded" IS NULL OR "IsSuperseded" IN (0,1)),
  "SupersededById" bigint NULL,
  "VerifiedAt" timestamp(3) NULL,
  "VerifiedBy" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("IdentityDocumentId"),
  CONSTRAINT "UQ_IdentityDocument_Tenant" UNIQUE ("TenantId", "IdentityDocumentId"),
  CONSTRAINT "CK_IdentityDocument_1" CHECK ("ExpiryDate" IS NULL OR "IssueDate" IS NULL OR "ExpiryDate" > "IssueDate"),
  CONSTRAINT "CK_IdentityDocument_2" CHECK ("SupersededById" IS NULL OR ("SupersededById" <> "IdentityDocumentId" AND "IsSuperseded" = 1)),
  CONSTRAINT "CK_IdentityDocument_3" CHECK ("IsSuperseded" = 0 OR "IsPrimary" = 0),
  CONSTRAINT "CK_IdentityDocument_4" CHECK ("VerifiedBy" IS NULL OR "VerifiedAt" IS NOT NULL),
  CONSTRAINT "CK_IdentityDocument_DocKind" CHECK ("DocKind" IS NULL OR "DocKind" IN ('NATIONAL_ID', 'RESIDENCE', 'PASSPORT', 'GCC_ID', 'COMMERCIAL_REG', 'OTHER_ORG'))
);
CREATE TABLE "pty"."Address" (
  "TenantId" integer NOT NULL,
  "AddressId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "OwnerType" varchar(11) NOT NULL,
  "OwnerId" bigint NOT NULL,
  "AddressType" varchar(11) NOT NULL,
  "IsPrimary" smallint NOT NULL DEFAULT 0,
  CHECK ("IsPrimary" IS NULL OR "IsPrimary" IN (0,1)),
  "IsCurrent" smallint NOT NULL DEFAULT 1,
  CHECK ("IsCurrent" IS NULL OR "IsCurrent" IN (0,1)),
  "CountryId" integer NOT NULL,
  "Region" varchar(100) NULL,
  "City" varchar(100) NULL,
  "District" varchar(100) NULL,
  "Street" varchar(150) NULL,
  "BuildingNumber" varchar(20) NULL,
  "UnitNumber" varchar(20) NULL,
  "PostalCode" varchar(20) NULL,
  "AdditionalNumber" varchar(20) NULL,
  "ShortCode" varchar(20) NULL,
  "PoBoxNumber" varchar(30) NULL,
  "FreeText" varchar(500) NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("AddressId"),
  CONSTRAINT "UQ_Address_Tenant" UNIQUE ("TenantId", "AddressId"),
  CONSTRAINT "CK_Address_1" CHECK ("IsPrimary" = 0 OR "IsCurrent" = 1),
  CONSTRAINT "CK_Address_2" CHECK ("AddressType" <> 'PO_BOX' OR "PoBoxNumber" IS NOT NULL),
  CONSTRAINT "CK_Address_OwnerType" CHECK ("OwnerType" IS NULL OR "OwnerType" IN ('PARTY', 'INSTITUTION', 'UNIT', 'CONTACT')),
  CONSTRAINT "CK_Address_AddressType" CHECK ("AddressType" IS NULL OR "AddressType" IN ('NATIONAL', 'RESIDENTIAL', 'WORK', 'PO_BOX', 'REGISTERED', 'OTHER'))
);
CREATE TABLE "pty"."ContactMethod" (
  "TenantId" integer NOT NULL,
  "ContactMethodId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "OwnerType" varchar(11) NOT NULL,
  "OwnerId" bigint NOT NULL,
  "Kind" varchar(10) NOT NULL,
  "Value" varchar(200) NOT NULL,
