  "CompanyId" bigint NOT NULL,
  "RequestId" bigint NOT NULL,
  "Amount" numeric(19,4) NOT NULL,
  "CurrencyId" integer NOT NULL,
  "RateToFacilityCcy" numeric(19,8) NULL,
  "Status" varchar(10) NOT NULL DEFAULT 'ACTIVE',
  "ExpiresOn" date NULL,
  "ConvertedUtilizationId" bigint NULL,
  "ReleasedOn" date NULL,
  "ReleaseReason" varchar(10) NULL,
  "OverLimit" smallint NOT NULL DEFAULT 0,
  CHECK ("OverLimit" IS NULL OR "OverLimit" IN (0,1)),
  "OverrideReason" varchar(500) NULL,
  "AcknowledgedWarnings" text NULL,
  "IdempotencyKey" varchar(100) NOT NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("LimitReservationId"),
  CONSTRAINT "UQ_LimitReservation_Tenant" UNIQUE ("TenantId", "LimitReservationId"),
  CONSTRAINT "UQ_LimitReservation_Scope_FacilityId" UNIQUE ("TenantId", "FacilityId", "LimitReservationId"),
  CONSTRAINT "UQ_LimitReservation_IdempotencyKey" UNIQUE ("TenantId", "IdempotencyKey"),
  CONSTRAINT "CK_LimitReservation_1" CHECK ("Amount" > 0),
  CONSTRAINT "CK_LimitReservation_2" CHECK ("RateToFacilityCcy" IS NULL OR "RateToFacilityCcy" > 0),
  CONSTRAINT "CK_LimitReservation_3" CHECK ("Status" <> 'CONVERTED' OR "ConvertedUtilizationId" IS NOT NULL),
  CONSTRAINT "CK_LimitReservation_4" CHECK ("Status" = 'CONVERTED' OR "ConvertedUtilizationId" IS NULL),
  CONSTRAINT "CK_LimitReservation_5" CHECK ("Status" <> 'RELEASED' OR ("ReleasedOn" IS NOT NULL AND "ReleaseReason" IS NOT NULL)),
  CONSTRAINT "CK_LimitReservation_6" CHECK ("Status" = 'RELEASED' OR ("ReleasedOn" IS NULL AND "ReleaseReason" IS NULL)),
  CONSTRAINT "CK_LimitReservation_7" CHECK ("OverLimit" = 0 OR "OverrideReason" IS NOT NULL),
  CONSTRAINT "CK_LimitReservation_Status" CHECK ("Status" IS NULL OR "Status" IN ('ACTIVE', 'CONVERTED', 'RELEASED')),
  CONSTRAINT "CK_LimitReservation_ReleaseReason" CHECK ("ReleaseReason" IS NULL OR "ReleaseReason" IN ('REJECTED', 'CANCELLED', 'EXPIRED', 'SUPERSEDED', 'MANUAL'))
);
CREATE TABLE "fac"."LimitMovement" (
  "TenantId" integer NOT NULL,
  "LimitMovementId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "FacilityId" bigint NOT NULL,
  "TargetKind" varchar(11) NOT NULL,
  "LimitReservationId" bigint NULL,
  "UtilizationId" bigint NULL,
  "TargetId" bigint GENERATED ALWAYS AS (CASE WHEN "LimitReservationId" IS NOT NULL THEN "LimitReservationId" ELSE "UtilizationId" END) STORED,
  "OpKind" varchar(10) NOT NULL,
  "CurrencyId" integer NOT NULL,
  "RequestedDelta" numeric(19,4) NULL,
  "AppliedDelta" numeric(19,4) NULL,
  "AmountBefore" numeric(19,4) NULL,
  "AmountAfter" numeric(19,4) NULL,
  "Reason" varchar(500) NULL,
  "IdempotencyKey" varchar(100) NOT NULL,
  "ActorUserId" bigint NOT NULL,
  "At" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  PRIMARY KEY ("LimitMovementId"),
  CONSTRAINT "UQ_LimitMovement_Tenant" UNIQUE ("TenantId", "LimitMovementId"),
  CONSTRAINT "UQ_LimitMovement_IdempotencyKey" UNIQUE ("TenantId", "IdempotencyKey"),
  CONSTRAINT "CK_LimitMovement_1" CHECK (("TargetKind" = 'RESERVATION' AND "LimitReservationId" IS NOT NULL AND "UtilizationId" IS NULL) OR ("TargetKind" = 'UTILIZATION' AND "UtilizationId" IS NOT NULL AND "LimitReservationId" IS NULL)),
  CONSTRAINT "CK_LimitMovement_2" CHECK ("AmountAfter" IS NULL OR "AmountAfter" >= 0),
  CONSTRAINT "CK_LimitMovement_3" CHECK ("AppliedDelta" IS NULL OR "RequestedDelta" IS NULL OR abs("AppliedDelta") <= abs("RequestedDelta")),
  CONSTRAINT "CK_LimitMovement_4" CHECK ("OpKind" <> 'ADJUST' OR "AmountBefore" IS NULL OR "AmountAfter" IS NULL OR "AppliedDelta" IS NULL OR "AmountAfter" = "AmountBefore" + "AppliedDelta"),
  CONSTRAINT "CK_LimitMovement_TargetKind" CHECK ("TargetKind" IS NULL OR "TargetKind" IN ('RESERVATION', 'UTILIZATION')),
  CONSTRAINT "CK_LimitMovement_OpKind" CHECK ("OpKind" IS NULL OR "OpKind" IN ('CREATE', 'ADJUST', 'CONVERT', 'RELEASE'))
);
CREATE TABLE "fac"."ValueConflict" (
  "TenantId" integer NOT NULL,
  "ValueConflictId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "FacilityId" bigint NOT NULL,
  "TargetEntity" varchar(60) NOT NULL,
  "TargetId" bigint NOT NULL,
  "FieldName" varchar(80) NOT NULL,
  "CandidateAValue" varchar(1000) NOT NULL,
  "CandidateASourceDocumentId" bigint NULL,
  "CandidateASourcePage" varchar(40) NULL,
  "CandidateAReadFromScan" smallint NOT NULL DEFAULT 0,
  CHECK ("CandidateAReadFromScan" IS NULL OR "CandidateAReadFromScan" IN (0,1)),
  "CandidateAOriginalText" varchar(2000) NULL,
  "CandidateAConfidence" varchar(26) NOT NULL DEFAULT 'ENTERED_NO_DOCUMENT',
  "CandidateBValue" varchar(1000) NOT NULL,
  "CandidateBSourceDocumentId" bigint NULL,
  "CandidateBSourcePage" varchar(40) NULL,
  "CandidateBReadFromScan" smallint NOT NULL DEFAULT 0,
  CHECK ("CandidateBReadFromScan" IS NULL OR "CandidateBReadFromScan" IN (0,1)),
  "CandidateBOriginalText" varchar(2000) NULL,
  "CandidateBConfidence" varchar(26) NOT NULL DEFAULT 'ENTERED_NO_DOCUMENT',
  "Status" varchar(10) NOT NULL DEFAULT 'OPEN',
  "ChosenSide" varchar(10) NULL,
  "ResolvedValue" varchar(1000) NULL,
  "ResolutionReason" varchar(1000) NULL,
  "ResolvedBy" bigint NULL,
  "ResolvedOn" timestamp(3) NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("ValueConflictId"),
  CONSTRAINT "UQ_ValueConflict_Tenant" UNIQUE ("TenantId", "ValueConflictId"),
  CONSTRAINT "CK_ValueConflict_1" CHECK ("Status" <> 'RESOLVED' OR ("ChosenSide" IS NOT NULL AND "ResolutionReason" IS NOT NULL AND "ResolvedBy" IS NOT NULL AND "ResolvedOn" IS NOT NULL)),
  CONSTRAINT "CK_ValueConflict_2" CHECK ("Status" = 'RESOLVED' OR ("ChosenSide" IS NULL AND "ResolvedBy" IS NULL AND "ResolvedOn" IS NULL)),
  CONSTRAINT "CK_ValueConflict_3" CHECK ("ChosenSide" IS NULL OR "ChosenSide" <> 'OTHER' OR "ResolvedValue" IS NOT NULL),
  CONSTRAINT "CK_ValueConflict_4" CHECK ("CandidateASourceDocumentId" IS NOT NULL AND "CandidateASourcePage" IS NOT NULL OR ("CandidateASourceDocumentId" IS NULL AND "CandidateAConfidence" = 'ENTERED_NO_DOCUMENT')),
  CONSTRAINT "CK_ValueConflict_5" CHECK ("CandidateBSourceDocumentId" IS NOT NULL AND "CandidateBSourcePage" IS NOT NULL OR ("CandidateBSourceDocumentId" IS NULL AND "CandidateBConfidence" = 'ENTERED_NO_DOCUMENT')),
  CONSTRAINT "CK_ValueConflict_CandidateAConfidence" CHECK ("CandidateAConfidence" IS NULL OR "CandidateAConfidence" IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT')),
  CONSTRAINT "CK_ValueConflict_CandidateBConfidence" CHECK ("CandidateBConfidence" IS NULL OR "CandidateBConfidence" IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT')),
  CONSTRAINT "CK_ValueConflict_Status" CHECK ("Status" IS NULL OR "Status" IN ('OPEN', 'RESOLVED')),
  CONSTRAINT "CK_ValueConflict_ChosenSide" CHECK ("ChosenSide" IS NULL OR "ChosenSide" IN ('A', 'B', 'OTHER'))
);
CREATE TABLE "prc"."TariffSchedule" (
  "TenantId" integer NOT NULL,
  "TariffScheduleId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "InstitutionId" bigint NOT NULL,
  "FacilityId" bigint NULL,
  "NameAr" varchar(200) NOT NULL,
  "NameEn" varchar(200) NULL,
  "VersionNo" integer NOT NULL,
  "EffectiveFrom" date NOT NULL,
  "EffectiveTo" date NULL,
  "Status" varchar(10) NOT NULL DEFAULT 'DRAFT',
  "SourceDocumentId" bigint NULL,
  "ApprovedBy" bigint NULL,
  "ApprovedOn" timestamp(3) NULL,
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("TariffScheduleId"),
  CONSTRAINT "UQ_TariffSchedule_Tenant" UNIQUE ("TenantId", "TariffScheduleId"),
  CONSTRAINT "UQ_TariffSchedule_PublicId" UNIQUE ("PublicId"),
  CONSTRAINT "UQ_TariffSchedule_InstitutionId_FacilityId_VersionNo" UNIQUE ("TenantId", "InstitutionId", "FacilityId", "VersionNo"),
  CONSTRAINT "CK_TariffSchedule_1" CHECK ("VersionNo" >= 1),
  CONSTRAINT "CK_TariffSchedule_2" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom"),
  CONSTRAINT "CK_TariffSchedule_3" CHECK ("Status" <> 'APPROVED' OR ("ApprovedBy" IS NOT NULL AND "ApprovedOn" IS NOT NULL)),
  CONSTRAINT "CK_TariffSchedule_Status" CHECK ("Status" IS NULL OR "Status" IN ('DRAFT', 'APPROVED', 'SUPERSEDED'))
);
CREATE TABLE "prc"."TariffItem" (
  "TenantId" integer NOT NULL,
  "TariffItemId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ScheduleId" bigint NOT NULL,
  "FeeTypeId" integer NOT NULL,
  "ItemCode" varchar(40) NOT NULL,
  "NameAr" varchar(200) NOT NULL,
  "NameEn" varchar(200) NULL,
  "ProductId" integer NULL,
  "ChargeKind" varchar(11) NOT NULL,
  "Rate" numeric(9,6) NULL,
  "FixedAmount" numeric(19,4) NULL,
  "PerMillionAmount" numeric(19,4) NULL,
  "PeriodBasis" varchar(18) NOT NULL DEFAULT 'FLAT',
  "PeriodDays" integer NULL,
  "MinAmount" numeric(19,4) NULL,
  "MaxAmount" numeric(19,4) NULL,
  "Locality" varchar(12) NOT NULL DEFAULT 'ANY',
  "TierCalcMode" varchar(10) NULL DEFAULT 'BAND',
  "PerMillionMode" varchar(15) NULL DEFAULT 'PRORATA',
  "VatTreatment" varchar(10) NOT NULL DEFAULT 'EXCLUSIVE',
  "CurrencyId" integer NULL,
  "SourceDocumentId" bigint NULL,
  "SourcePage" varchar(40) NULL,
  "ReadFromScan" smallint NOT NULL DEFAULT 0,
  CHECK ("ReadFromScan" IS NULL OR "ReadFromScan" IN (0,1)),
  "OriginalText" varchar(2000) NULL,
  "NoSourceReason" varchar(300) NULL,
  "Confidence" varchar(26) NOT NULL DEFAULT 'ENTERED_NO_DOCUMENT',
  "VerifiedBy" bigint NULL,
  "VerifiedOn" timestamp(3) NULL,
  "ConflictId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("TariffItemId"),
  CONSTRAINT "UQ_TariffItem_Tenant" UNIQUE ("TenantId", "TariffItemId"),
  CONSTRAINT "UQ_TariffItem_ScheduleId_ItemCode" UNIQUE ("TenantId", "ScheduleId", "ItemCode"),
  CONSTRAINT "CK_TariffItem_1" CHECK ("ChargeKind" <> 'PERCENT' OR ("Rate" IS NOT NULL AND "FixedAmount" IS NULL AND "PerMillionAmount" IS NULL)),
  CONSTRAINT "CK_TariffItem_2" CHECK ("ChargeKind" <> 'FIXED' OR ("FixedAmount" IS NOT NULL AND "Rate" IS NULL AND "PerMillionAmount" IS NULL)),
  CONSTRAINT "CK_TariffItem_3" CHECK ("ChargeKind" <> 'PER_MILLION' OR ("PerMillionAmount" IS NOT NULL AND "Rate" IS NULL AND "FixedAmount" IS NULL)),
  CONSTRAINT "CK_TariffItem_4" CHECK ("ChargeKind" <> 'TIERED' OR ("Rate" IS NULL AND "FixedAmount" IS NULL AND "PerMillionAmount" IS NULL)),
  CONSTRAINT "CK_TariffItem_5" CHECK ("Rate" IS NULL OR ("Rate" >= 0 AND "Rate" <= 100)),
  CONSTRAINT "CK_TariffItem_6" CHECK ("PeriodBasis" <> 'PER_PERIOD_OR_PART' OR "PeriodDays" IS NOT NULL),
  CONSTRAINT "CK_TariffItem_7" CHECK ("PeriodDays" IS NULL OR "PeriodDays" > 0),
  CONSTRAINT "CK_TariffItem_8" CHECK ("MinAmount" IS NULL OR "MinAmount" >= 0),
  CONSTRAINT "CK_TariffItem_9" CHECK ("MinAmount" IS NULL OR "MaxAmount" IS NULL OR "MinAmount" <= "MaxAmount"),
  CONSTRAINT "CK_TariffItem_10" CHECK ("SourceDocumentId" IS NOT NULL AND "SourcePage" IS NOT NULL OR ("SourceDocumentId" IS NULL AND "Confidence" = 'ENTERED_NO_DOCUMENT')),
  CONSTRAINT "CK_TariffItem_11" CHECK ("Confidence" <> 'CONFIRMED_AGAINST_ORIGINAL' OR ("VerifiedBy" IS NOT NULL AND "VerifiedOn" IS NOT NULL)),
  CONSTRAINT "CK_TariffItem_ChargeKind" CHECK ("ChargeKind" IS NULL OR "ChargeKind" IN ('PERCENT', 'FIXED', 'PER_MILLION', 'TIERED')),
  CONSTRAINT "CK_TariffItem_PeriodBasis" CHECK ("PeriodBasis" IS NULL OR "PeriodBasis" IN ('FLAT', 'PER_ANNUM', 'PER_PERIOD_OR_PART')),
  CONSTRAINT "CK_TariffItem_Locality" CHECK ("Locality" IS NULL OR "Locality" IN ('ANY', 'INSIDE_BANK', 'OUTSIDE_BANK')),
  CONSTRAINT "CK_TariffItem_TierCalcMode" CHECK ("TierCalcMode" IS NULL OR "TierCalcMode" IN ('BAND', 'WHOLE')),
  CONSTRAINT "CK_TariffItem_PerMillionMode" CHECK ("PerMillionMode" IS NULL OR "PerMillionMode" IN ('PRORATA', 'STARTED_MILLION')),
  CONSTRAINT "CK_TariffItem_VatTreatment" CHECK ("VatTreatment" IS NULL OR "VatTreatment" IN ('EXCLUSIVE', 'INCLUSIVE', 'EXEMPT')),
  CONSTRAINT "CK_TariffItem_Confidence" CHECK ("Confidence" IS NULL OR "Confidence" IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
CREATE TABLE "prc"."TariffTier" (
  "TenantId" integer NOT NULL,
  "TariffTierId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "TariffItemId" bigint NOT NULL,
  "AmountFrom" numeric(19,4) NULL,
  "AmountTo" numeric(19,4) NULL,
  "PeriodFromDays" integer NULL,
  "PeriodToDays" integer NULL,
  "Rate" numeric(9,6) NULL,
  "FixedAmount" numeric(19,4) NULL,
  "MinAmount" numeric(19,4) NULL,
  "SortOrder" integer NOT NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("TariffTierId"),
  CONSTRAINT "UQ_TariffTier_Tenant" UNIQUE ("TenantId", "TariffTierId"),
  CONSTRAINT "UQ_TariffTier_TariffItemId_SortOrder" UNIQUE ("TenantId", "TariffItemId", "SortOrder"),
  CONSTRAINT "UQ_TariffTier_TariffItemId_AmountFrom_PeriodFromDays" UNIQUE ("TenantId", "TariffItemId", "AmountFrom", "PeriodFromDays"),
  CONSTRAINT "CK_TariffTier_1" CHECK ("AmountFrom" IS NULL OR "AmountFrom" >= 0),
  CONSTRAINT "CK_TariffTier_2" CHECK ("AmountTo" IS NULL OR "AmountFrom" IS NULL OR "AmountTo" > "AmountFrom"),
  CONSTRAINT "CK_TariffTier_3" CHECK ("PeriodFromDays" IS NULL OR "PeriodFromDays" >= 0),
  CONSTRAINT "CK_TariffTier_4" CHECK ("PeriodToDays" IS NULL OR "PeriodFromDays" IS NULL OR "PeriodToDays" >= "PeriodFromDays"),
  CONSTRAINT "CK_TariffTier_5" CHECK ("Rate" IS NOT NULL OR "FixedAmount" IS NOT NULL),
  CONSTRAINT "CK_TariffTier_6" CHECK ("Rate" IS NULL OR "FixedAmount" IS NULL),
  CONSTRAINT "CK_TariffTier_7" CHECK ("Rate" IS NULL OR ("Rate" >= 0 AND "Rate" <= 100)),
  CONSTRAINT "CK_TariffTier_8" CHECK ("MinAmount" IS NULL OR "MinAmount" >= 0)
);
CREATE TABLE "prc"."PricingRule" (
  "TenantId" integer NOT NULL,
  "PricingRuleId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "FacilityId" bigint NOT NULL,
  "ScopeLimitId" bigint NULL,
  "ScopeLimitProductLineId" bigint NULL,
  "ScopeProductId" integer NULL,
  "ScopeCompanyId" bigint NULL,
  "ComponentKind" varchar(18) NOT NULL,
  "RateState" varchar(26) NOT NULL DEFAULT 'SET',
  "FeeTypeId" integer NULL,
  "FinancingTypeId" integer NULL,
  "Method" varchar(17) NOT NULL,
  "TariffItemId" bigint NULL,
  "AddOnPct" numeric(9,6) NULL,
  "BaseRateId" integer NULL,
  "MarginPct" numeric(9,6) NULL,
  "BaseFloorPct" numeric(9,6) NULL,
  "RatePct" numeric(9,6) NULL,
  "RateRangeLowPct" numeric(9,6) NULL,
  "RateRangeHighPct" numeric(9,6) NULL,
  "FixedAmount" numeric(19,4) NULL,
  "PerMillionAmount" numeric(19,4) NULL,
  "CurrencyId" integer NULL,
  "PeriodBasis" varchar(18) NULL,
  "PeriodDays" integer NULL,
  "MinFeeAmount" numeric(19,4) NULL,
  "MaxFeeAmount" numeric(19,4) NULL,
  "RateFixing" varchar(18) NULL,
  "RepricingMonths" integer NULL,
  "DayCount" varchar(10) NULL,
  "VatExclusive" smallint NOT NULL DEFAULT 1,
  CHECK ("VatExclusive" IS NULL OR "VatExclusive" IN (0,1)),
  "BenchmarkReplacement" varchar(15) NOT NULL DEFAULT 'NONE',
  "ReplacementText" varchar(1000) NULL,
  "BankMayChange" varchar(21) NOT NULL DEFAULT 'NO',
  "ObjectionDays" integer NULL,
  "ObjectionDaysKind" varchar(10) NULL,
  "TriggerEvent" varchar(35) NULL,
  "EffectiveFrom" date NOT NULL,
  "EffectiveTo" date NULL,
  "Retroactive" smallint NOT NULL DEFAULT 0,
  CHECK ("Retroactive" IS NULL OR "Retroactive" IN (0,1)),
  "RetroactiveReason" varchar(500) NULL,
  "FromRevision" integer NOT NULL DEFAULT 1,
  "ToRevision" integer NULL,
  "SupersedesId" bigint NULL,
  "SourceDocumentId" bigint NULL,
  "SourcePage" varchar(40) NULL,
  "ReadFromScan" smallint NOT NULL DEFAULT 0,
  CHECK ("ReadFromScan" IS NULL OR "ReadFromScan" IN (0,1)),
  "OriginalText" varchar(2000) NULL,
  "NoSourceReason" varchar(300) NULL,
  "Confidence" varchar(26) NOT NULL DEFAULT 'ENTERED_NO_DOCUMENT',
  "VerifiedBy" bigint NULL,
  "VerifiedOn" timestamp(3) NULL,
  "ConflictId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("PricingRuleId"),
  CONSTRAINT "UQ_PricingRule_Tenant" UNIQUE ("TenantId", "PricingRuleId"),
  CONSTRAINT "UQ_PricingRule_Scope_FacilityId" UNIQUE ("TenantId", "FacilityId", "PricingRuleId"),
  CONSTRAINT "CK_PricingRule_1" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom"),
  CONSTRAINT "CK_PricingRule_2" CHECK ("ComponentKind" <> 'FINANCING_RETURN' OR "FeeTypeId" IS NULL),
  CONSTRAINT "CK_PricingRule_3" CHECK ("ComponentKind" = 'FINANCING_RETURN' OR ("FeeTypeId" IS NOT NULL AND "FinancingTypeId" IS NULL)),
  CONSTRAINT "CK_PricingRule_4" CHECK ("ComponentKind" <> 'PENALTY_NON_INCOME' OR "TriggerEvent" IS NOT NULL),
  CONSTRAINT "CK_PricingRule_5" CHECK ("ComponentKind" = 'PENALTY_NON_INCOME' OR "TriggerEvent" IS NULL),
  CONSTRAINT "CK_PricingRule_6" CHECK ("RateState" <> 'NOT_SPECIFIED_IN_AGREEMENT' OR ("AddOnPct" IS NULL AND "MarginPct" IS NULL AND "RatePct" IS NULL AND "RateRangeLowPct" IS NULL AND "RateRangeHighPct" IS NULL AND "FixedAmount" IS NULL AND "PerMillionAmount" IS NULL)),
  CONSTRAINT "CK_PricingRule_7" CHECK ("RateState" <> 'SET' OR "Method" <> 'TARIFF_AS_IS' OR "TariffItemId" IS NOT NULL),
  CONSTRAINT "CK_PricingRule_8" CHECK ("RateState" <> 'SET' OR "Method" <> 'TARIFF_PLUS_ADDON' OR ("TariffItemId" IS NOT NULL AND "AddOnPct" IS NOT NULL)),
  CONSTRAINT "CK_PricingRule_9" CHECK ("RateState" <> 'SET' OR "Method" <> 'BASE_PLUS_MARGIN' OR ("BaseRateId" IS NOT NULL AND "MarginPct" IS NOT NULL AND "RateFixing" IS NOT NULL AND "DayCount" IS NOT NULL)),
  CONSTRAINT "CK_PricingRule_10" CHECK ("RateState" <> 'SET' OR "Method" <> 'PERCENT_OF_AMOUNT' OR "RatePct" IS NOT NULL OR ("RateRangeLowPct" IS NOT NULL AND "RateRangeHighPct" IS NOT NULL)),
  CONSTRAINT "CK_PricingRule_11" CHECK ("RateState" <> 'SET' OR "Method" <> 'FIXED_AMOUNT' OR "FixedAmount" IS NOT NULL),
  CONSTRAINT "CK_PricingRule_12" CHECK ("RateState" <> 'SET' OR "Method" <> 'PER_MILLION' OR "PerMillionAmount" IS NOT NULL),
  CONSTRAINT "CK_PricingRule_13" CHECK ("Method" IN ('TARIFF_AS_IS','TARIFF_PLUS_ADDON') OR "TariffItemId" IS NULL),
  CONSTRAINT "CK_PricingRule_14" CHECK ("Method" = 'TARIFF_PLUS_ADDON' OR "AddOnPct" IS NULL),
  CONSTRAINT "CK_PricingRule_15" CHECK ("Method" = 'BASE_PLUS_MARGIN' OR ("BaseRateId" IS NULL AND "MarginPct" IS NULL AND "BaseFloorPct" IS NULL AND "RateFixing" IS NULL AND "RepricingMonths" IS NULL)),
  CONSTRAINT "CK_PricingRule_16" CHECK ("Method" = 'PERCENT_OF_AMOUNT' OR ("RatePct" IS NULL AND "RateRangeLowPct" IS NULL AND "RateRangeHighPct" IS NULL)),
  CONSTRAINT "CK_PricingRule_17" CHECK ("Method" = 'FIXED_AMOUNT' OR "FixedAmount" IS NULL),
  CONSTRAINT "CK_PricingRule_18" CHECK ("Method" = 'PER_MILLION' OR "PerMillionAmount" IS NULL),
  CONSTRAINT "CK_PricingRule_19" CHECK ("RatePct" IS NULL OR ("RateRangeLowPct" IS NULL AND "RateRangeHighPct" IS NULL)),
  CONSTRAINT "CK_PricingRule_20" CHECK (("RateRangeLowPct" IS NULL AND "RateRangeHighPct" IS NULL) OR ("RateRangeLowPct" IS NOT NULL AND "RateRangeHighPct" IS NOT NULL AND "RateRangeLowPct" <= "RateRangeHighPct")),
  CONSTRAINT "CK_PricingRule_21" CHECK ("RatePct" IS NULL OR ("RatePct" >= 0 AND "RatePct" <= 100)),
  CONSTRAINT "CK_PricingRule_22" CHECK ("FixedAmount" IS NULL OR "FixedAmount" >= 0),
  CONSTRAINT "CK_PricingRule_23" CHECK ("PerMillionAmount" IS NULL OR "PerMillionAmount" >= 0),
  CONSTRAINT "CK_PricingRule_24" CHECK ("MinFeeAmount" IS NULL OR "MinFeeAmount" >= 0),
  CONSTRAINT "CK_PricingRule_25" CHECK ("MinFeeAmount" IS NULL OR "MaxFeeAmount" IS NULL OR "MinFeeAmount" <= "MaxFeeAmount"),
  CONSTRAINT "CK_PricingRule_26" CHECK ("PeriodDays" IS NULL OR "PeriodDays" > 0),
  CONSTRAINT "CK_PricingRule_27" CHECK ("PeriodBasis" IS NULL OR "PeriodBasis" <> 'PER_PERIOD_OR_PART' OR "PeriodDays" IS NOT NULL OR "Method" IN ('TARIFF_AS_IS','TARIFF_PLUS_ADDON','TIERED')),
  CONSTRAINT "CK_PricingRule_28" CHECK ("PeriodBasis" IS NULL OR "PeriodBasis" <> 'PER_ANNUM' OR "DayCount" IS NOT NULL),
  CONSTRAINT "CK_PricingRule_29" CHECK ("RepricingMonths" IS NULL OR "RepricingMonths" > 0),
  CONSTRAINT "CK_PricingRule_30" CHECK ("RateFixing" IS NULL OR "RateFixing" <> 'FLOATING' OR "RateState" <> 'SET' OR "RepricingMonths" IS NOT NULL),
  CONSTRAINT "CK_PricingRule_31" CHECK ("BenchmarkReplacement" <> 'NAMED_FALLBACK' OR "ReplacementText" IS NOT NULL),
  CONSTRAINT "CK_PricingRule_32" CHECK ("BankMayChange" <> 'WITH_NOTICE_OBJECTION' OR ("ObjectionDays" IS NOT NULL AND "ObjectionDaysKind" IS NOT NULL)),
  CONSTRAINT "CK_PricingRule_33" CHECK ("ObjectionDays" IS NULL OR "ObjectionDays" >= 0),
  CONSTRAINT "CK_PricingRule_34" CHECK ("Retroactive" = 0 OR "RetroactiveReason" IS NOT NULL),
  CONSTRAINT "CK_PricingRule_35" CHECK ("ToRevision" IS NULL OR "ToRevision" >= "FromRevision"),
  CONSTRAINT "CK_PricingRule_36" CHECK ("SourceDocumentId" IS NOT NULL AND "SourcePage" IS NOT NULL OR ("SourceDocumentId" IS NULL AND "Confidence" = 'ENTERED_NO_DOCUMENT')),
  CONSTRAINT "CK_PricingRule_37" CHECK ("Confidence" <> 'CONFIRMED_AGAINST_ORIGINAL' OR ("VerifiedBy" IS NOT NULL AND "VerifiedOn" IS NOT NULL)),
  CONSTRAINT "CK_PricingRule_ComponentKind" CHECK ("ComponentKind" IS NULL OR "ComponentKind" IN ('FEE', 'FINANCING_RETURN', 'PENALTY_NON_INCOME')),
  CONSTRAINT "CK_PricingRule_RateState" CHECK ("RateState" IS NULL OR "RateState" IN ('SET', 'NOT_SPECIFIED_IN_AGREEMENT')),
  CONSTRAINT "CK_PricingRule_Method" CHECK ("Method" IS NULL OR "Method" IN ('TARIFF_AS_IS', 'TARIFF_PLUS_ADDON', 'BASE_PLUS_MARGIN', 'PERCENT_OF_AMOUNT', 'FIXED_AMOUNT', 'PER_MILLION', 'TIERED')),
  CONSTRAINT "CK_PricingRule_PeriodBasis" CHECK ("PeriodBasis" IS NULL OR "PeriodBasis" IN ('FLAT', 'PER_ANNUM', 'PER_PERIOD_OR_PART')),
  CONSTRAINT "CK_PricingRule_RateFixing" CHECK ("RateFixing" IS NULL OR "RateFixing" IN ('FIXED_FOR_CONTRACT', 'FLOATING')),
  CONSTRAINT "CK_PricingRule_DayCount" CHECK ("DayCount" IS NULL OR "DayCount" IN ('ACT_360', 'ACT_365')),
  CONSTRAINT "CK_PricingRule_BenchmarkReplacement" CHECK ("BenchmarkReplacement" IS NULL OR "BenchmarkReplacement" IN ('NONE', 'BANK_DETERMINES', 'NAMED_FALLBACK')),
  CONSTRAINT "CK_PricingRule_BankMayChange" CHECK ("BankMayChange" IS NULL OR "BankMayChange" IN ('NO', 'WITH_NOTICE_OBJECTION', 'UNILATERAL')),
  CONSTRAINT "CK_PricingRule_ObjectionDaysKind" CHECK ("ObjectionDaysKind" IS NULL OR "ObjectionDaysKind" IN ('CALENDAR', 'BUSINESS')),
  CONSTRAINT "CK_PricingRule_TriggerEvent" CHECK ("TriggerEvent" IS NULL OR "TriggerEvent" IN ('LATE_PAYMENT', 'LATE_GUARANTEE_PAYMENT_AFTER_DEMAND', 'OTHER')),
  CONSTRAINT "CK_PricingRule_Confidence" CHECK ("Confidence" IS NULL OR "Confidence" IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
CREATE TABLE "prc"."PricingTier" (
  "TenantId" integer NOT NULL,
  "PricingTierId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "FacilityId" bigint NOT NULL,
  "PricingRuleId" bigint NOT NULL,
  "AmountFrom" numeric(19,4) NULL,
  "AmountTo" numeric(19,4) NULL,
  "PeriodFromDays" integer NULL,
  "PeriodToDays" integer NULL,
  "RatePct" numeric(9,6) NULL,
  "MarginPct" numeric(9,6) NULL,
  "FixedAmount" numeric(19,4) NULL,
  "SortOrder" integer NOT NULL,
  "FromRevision" integer NOT NULL DEFAULT 1,
  "ToRevision" integer NULL,
  "SupersedesId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("PricingTierId"),
  CONSTRAINT "UQ_PricingTier_Tenant" UNIQUE ("TenantId", "PricingTierId"),
  CONSTRAINT "CK_PricingTier_1" CHECK ("AmountFrom" IS NULL OR "AmountFrom" >= 0),
  CONSTRAINT "CK_PricingTier_2" CHECK ("AmountTo" IS NULL OR "AmountFrom" IS NULL OR "AmountTo" > "AmountFrom"),
  CONSTRAINT "CK_PricingTier_3" CHECK ("PeriodFromDays" IS NULL OR "PeriodFromDays" >= 0),
  CONSTRAINT "CK_PricingTier_4" CHECK ("PeriodToDays" IS NULL OR "PeriodFromDays" IS NULL OR "PeriodToDays" >= "PeriodFromDays"),
  CONSTRAINT "CK_PricingTier_5" CHECK ((CASE WHEN "RatePct" IS NULL THEN 0 ELSE 1 END + CASE WHEN "MarginPct" IS NULL THEN 0 ELSE 1 END + CASE WHEN "FixedAmount" IS NULL THEN 0 ELSE 1 END) = 1),
  CONSTRAINT "CK_PricingTier_6" CHECK ("RatePct" IS NULL OR ("RatePct" >= 0 AND "RatePct" <= 100)),
  CONSTRAINT "CK_PricingTier_7" CHECK ("FixedAmount" IS NULL OR "FixedAmount" >= 0),
  CONSTRAINT "CK_PricingTier_8" CHECK ("ToRevision" IS NULL OR "ToRevision" >= "FromRevision")
);
CREATE TABLE "cmp"."TermType" (
  "TenantId" integer NOT NULL,
  "TermTypeId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Code" varchar(80) NOT NULL,
  "NameAr" varchar(200) NOT NULL,
  "NameEn" varchar(200) NULL,
  "Description" varchar(500) NULL,
  "IsActive" smallint NOT NULL DEFAULT 1,
  CHECK ("IsActive" IS NULL OR "IsActive" IN (0,1)),
  "IsSystem" smallint NOT NULL DEFAULT 0,
  CHECK ("IsSystem" IS NULL OR "IsSystem" IN (0,1)),
  "IsLocked" smallint NOT NULL DEFAULT 0,
  CHECK ("IsLocked" IS NULL OR "IsLocked" IN (0,1)),
  "SortOrder" integer NOT NULL DEFAULT 0,
  "SeedKey" varchar(80) NULL,
  "ExternalCode" varchar(80) NULL,
  "Category" varchar(10) NOT NULL,
  "ValueKind" varchar(10) NOT NULL,
  "Unit" varchar(20) NOT NULL,
  "DefaultBound" varchar(10) NOT NULL DEFAULT 'EXACT',
  "Direction" varchar(13) NOT NULL DEFAULT 'NEUTRAL',
  "ScopeKinds" varchar(44) NOT NULL,
  "SourceBinding" varchar(200) NULL,
  "EnumOptions" text NULL,
  "IsComparable" smallint NOT NULL DEFAULT 1,
  CHECK ("IsComparable" IS NULL OR "IsComparable" IN (0,1)),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("TermTypeId"),
  CONSTRAINT "UQ_TermType_Tenant" UNIQUE ("TenantId", "TermTypeId"),
  CONSTRAINT "UQ_TermType_Code" UNIQUE ("TenantId", "Code"),
  CONSTRAINT "CK_TermType_1" CHECK ("ScopeKinds" <> ''),
  CONSTRAINT "CK_TermType_2" CHECK ("ValueKind" <> 'ENUM' OR "EnumOptions" IS NOT NULL),
  CONSTRAINT "CK_TermType_3" CHECK ("ValueKind" = 'ENUM' OR "EnumOptions" IS NULL),
  CONSTRAINT "CK_TermType_Category" CHECK ("Category" IS NULL OR "Category" IN ('PRICING', 'DURATION', 'COLLATERAL', 'COVENANT', 'OTHER')),
  CONSTRAINT "CK_TermType_ValueKind" CHECK ("ValueKind" IS NULL OR "ValueKind" IN ('PERCENT', 'AMOUNT', 'DAYS', 'MONTHS', 'COUNT', 'BOOLEAN', 'ENUM', 'TEXT')),
  CONSTRAINT "CK_TermType_DefaultBound" CHECK ("DefaultBound" IS NULL OR "DefaultBound" IN ('EXACT', 'MAX', 'MIN')),
  CONSTRAINT "CK_TermType_Direction" CHECK ("Direction" IS NULL OR "Direction" IN ('LOWER_BETTER', 'HIGHER_BETTER', 'NEUTRAL'))
);
CREATE TABLE "cmp"."TermValue" (
  "TenantId" integer NOT NULL,
  "TermValueId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "FacilityId" bigint NOT NULL,
  "TermTypeId" integer NOT NULL,
  "OtherLabel" varchar(200) NULL,
  "LimitId" bigint NULL,
  "LimitProductLineId" bigint NULL,
  "ProductId" integer NULL,
  "CompanyId" bigint NULL,
  "ValueState" varchar(26) NOT NULL DEFAULT 'SPECIFIED',
  "ValueNumber" numeric(19,6) NULL,
  "ValueText" varchar(1000) NULL,
  "ValueBool" smallint NULL,
  CHECK ("ValueBool" IS NULL OR "ValueBool" IN (0,1)),
  "ValueEnum" varchar(100) NULL,
  "Unit" varchar(20) NOT NULL,
  "CurrencyId" integer NULL,
  "Bound" varchar(10) NOT NULL DEFAULT 'EXACT',
  "NormalizedValue" numeric(19,6) NULL,
  "Origin" varchar(10) NOT NULL DEFAULT 'ENTERED',
  "ProjectedFrom" varchar(120) NULL,
  "EffectiveFrom" date NOT NULL,
  "EffectiveTo" date NULL,
  "FromRevision" integer NOT NULL DEFAULT 1,
  "ToRevision" integer NULL,
  "SupersedesId" bigint NULL,
  "SourceDocumentId" bigint NULL,
  "SourcePage" varchar(40) NULL,
  "ReadFromScan" smallint NOT NULL DEFAULT 0,
  CHECK ("ReadFromScan" IS NULL OR "ReadFromScan" IN (0,1)),
  "OriginalText" varchar(2000) NULL,
  "NoSourceReason" varchar(300) NULL,
  "Confidence" varchar(26) NOT NULL DEFAULT 'ENTERED_NO_DOCUMENT',
  "VerifiedBy" bigint NULL,
  "VerifiedOn" timestamp(3) NULL,
  "ConflictId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("TermValueId"),
  CONSTRAINT "UQ_TermValue_Tenant" UNIQUE ("TenantId", "TermValueId"),
  CONSTRAINT "CK_TermValue_1" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom"),
  CONSTRAINT "CK_TermValue_2" CHECK ("ValueState" = 'SPECIFIED' OR ("ValueNumber" IS NULL AND "ValueText" IS NULL AND "ValueBool" IS NULL AND "ValueEnum" IS NULL AND "NormalizedValue" IS NULL)),
  CONSTRAINT "CK_TermValue_3" CHECK ("ValueState" <> 'SPECIFIED' OR (CASE WHEN "ValueNumber" IS NULL THEN 0 ELSE 1 END + CASE WHEN "ValueText" IS NULL THEN 0 ELSE 1 END + CASE WHEN "ValueBool" IS NULL THEN 0 ELSE 1 END + CASE WHEN "ValueEnum" IS NULL THEN 0 ELSE 1 END) = 1),
  CONSTRAINT "CK_TermValue_4" CHECK ("NormalizedValue" IS NULL OR "ValueNumber" IS NOT NULL),
  CONSTRAINT "CK_TermValue_5" CHECK ("Origin" <> 'PROJECTED' OR "ProjectedFrom" IS NOT NULL),
  CONSTRAINT "CK_TermValue_6" CHECK ("Origin" = 'PROJECTED' OR "ProjectedFrom" IS NULL),
  CONSTRAINT "CK_TermValue_7" CHECK ("ToRevision" IS NULL OR "ToRevision" >= "FromRevision"),
  CONSTRAINT "CK_TermValue_8" CHECK ("SourceDocumentId" IS NOT NULL AND "SourcePage" IS NOT NULL OR ("SourceDocumentId" IS NULL AND "Confidence" = 'ENTERED_NO_DOCUMENT')),
  CONSTRAINT "CK_TermValue_9" CHECK ("Confidence" <> 'CONFIRMED_AGAINST_ORIGINAL' OR ("VerifiedBy" IS NOT NULL AND "VerifiedOn" IS NOT NULL)),
  CONSTRAINT "CK_TermValue_ValueState" CHECK ("ValueState" IS NULL OR "ValueState" IN ('SPECIFIED', 'NOT_SPECIFIED_IN_AGREEMENT', 'NOT_APPLICABLE', 'UNKNOWN')),
  CONSTRAINT "CK_TermValue_Bound" CHECK ("Bound" IS NULL OR "Bound" IN ('EXACT', 'MAX', 'MIN')),
  CONSTRAINT "CK_TermValue_Origin" CHECK ("Origin" IS NULL OR "Origin" IN ('ENTERED', 'PROJECTED')),
  CONSTRAINT "CK_TermValue_Confidence" CHECK ("Confidence" IS NULL OR "Confidence" IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
CREATE TABLE "col"."Collateral" (
  "TenantId" integer NOT NULL,
  "CollateralId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CollateralTypeId" integer NOT NULL,
  "TitleAr" varchar(300) NOT NULL,
  "Description" varchar(2000) NULL,
  "OwnerPartyId" bigint NULL,
  "Attributes" text NULL,
  "Status" varchar(10) NOT NULL DEFAULT 'DRAFT',
  "ApprovalState" varchar(10) NOT NULL DEFAULT 'DRAFT',
  "ApprovedBy" bigint NULL,
  "ApprovedOn" timestamp(3) NULL,
  "SupersedesId" bigint NULL,
  "GrantedOn" date NULL,
  "ReleasedOn" date NULL,
  "ReleaseReason" varchar(500) NULL,
  "ReleaseDocumentId" bigint NULL,
  "SourceDocumentId" bigint NULL,
  "SourcePage" varchar(40) NULL,
  "ReadFromScan" smallint NOT NULL DEFAULT 0,
  CHECK ("ReadFromScan" IS NULL OR "ReadFromScan" IN (0,1)),
  "OriginalText" varchar(2000) NULL,
  "NoSourceReason" varchar(300) NULL,
  "Confidence" varchar(26) NOT NULL DEFAULT 'ENTERED_NO_DOCUMENT',
  "VerifiedBy" bigint NULL,
  "VerifiedOn" timestamp(3) NULL,
  "ConflictId" bigint NULL,
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CollateralId"),
  CONSTRAINT "UQ_Collateral_Tenant" UNIQUE ("TenantId", "CollateralId"),
  CONSTRAINT "UQ_Collateral_PublicId" UNIQUE ("PublicId"),
  CONSTRAINT "CK_Collateral_1" CHECK ("Status" = 'DRAFT' OR "ApprovalState" = 'APPROVED'),
  CONSTRAINT "CK_Collateral_2" CHECK ("ApprovalState" <> 'APPROVED' OR "Status" <> 'DRAFT'),
  CONSTRAINT "CK_Collateral_3" CHECK ("ApprovalState" <> 'APPROVED' OR ("ApprovedBy" IS NOT NULL AND "ApprovedOn" IS NOT NULL)),
  CONSTRAINT "CK_Collateral_4" CHECK ("Status" <> 'RELEASED' OR ("ReleasedOn" IS NOT NULL AND "ReleaseReason" IS NOT NULL)),
  CONSTRAINT "CK_Collateral_5" CHECK ("Status" = 'RELEASED' OR ("ReleasedOn" IS NULL AND "ReleaseReason" IS NULL AND "ReleaseDocumentId" IS NULL)),
  CONSTRAINT "CK_Collateral_6" CHECK ("GrantedOn" IS NULL OR "ReleasedOn" IS NULL OR "ReleasedOn" >= "GrantedOn"),
  CONSTRAINT "CK_Collateral_7" CHECK ("SupersedesId" IS NULL OR "SupersedesId" <> "CollateralId"),
  CONSTRAINT "CK_Collateral_8" CHECK ("SourceDocumentId" IS NOT NULL AND "SourcePage" IS NOT NULL OR ("SourceDocumentId" IS NULL AND "Confidence" = 'ENTERED_NO_DOCUMENT')),
  CONSTRAINT "CK_Collateral_9" CHECK ("Confidence" <> 'CONFIRMED_AGAINST_ORIGINAL' OR ("VerifiedBy" IS NOT NULL AND "VerifiedOn" IS NOT NULL)),
  CONSTRAINT "CK_Collateral_Status" CHECK ("Status" IS NULL OR "Status" IN ('DRAFT', 'ACTIVE', 'RELEASED', 'EXPIRED')),
  CONSTRAINT "CK_Collateral_ApprovalState" CHECK ("ApprovalState" IS NULL OR "ApprovalState" IN ('DRAFT', 'APPROVED')),
  CONSTRAINT "CK_Collateral_Confidence" CHECK ("Confidence" IS NULL OR "Confidence" IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
CREATE TABLE "col"."CollateralLink" (
  "TenantId" integer NOT NULL,
  "CollateralLinkId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CollateralId" bigint NOT NULL,
  "FacilityId" bigint NOT NULL,
  "LimitId" bigint NULL,
  "CoverageAmount" numeric(19,4) NULL,
  "LienRank" integer NULL,
  "LinkedOn" date NOT NULL,
  "UnlinkedOn" date NULL,
  "FromRevision" integer NOT NULL DEFAULT 1,
  "ToRevision" integer NULL,
  "SupersedesId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CollateralLinkId"),
  CONSTRAINT "UQ_CollateralLink_Tenant" UNIQUE ("TenantId", "CollateralLinkId"),
  CONSTRAINT "CK_CollateralLink_1" CHECK ("CoverageAmount" IS NULL OR "CoverageAmount" > 0),
  CONSTRAINT "CK_CollateralLink_2" CHECK ("LienRank" IS NULL OR "LienRank" >= 1),
  CONSTRAINT "CK_CollateralLink_3" CHECK ("UnlinkedOn" IS NULL OR "UnlinkedOn" >= "LinkedOn"),
  CONSTRAINT "CK_CollateralLink_4" CHECK ("ToRevision" IS NULL OR "ToRevision" >= "FromRevision")
);
CREATE TABLE "col"."Guarantee" (
  "TenantId" integer NOT NULL,
  "GuaranteeId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CollateralId" bigint NOT NULL,
  "GuarantorPartyId" bigint NOT NULL,
  "GuarantorIdentityDocumentId" bigint NULL,
  "GuaranteeForm" varchar(33) NOT NULL,
  "IsJointSeveral" smallint NOT NULL,
  CHECK ("IsJointSeveral" IS NULL OR "IsJointSeveral" IN (0,1)),
  "AmountMode" varchar(11) NOT NULL,
  "Amount" numeric(19,4) NULL,
  "CurrencyId" integer NULL,
  "SignedOn" date NULL,
  "ValidTo" date NULL,
  "DeedDocumentId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("GuaranteeId"),
  CONSTRAINT "UQ_Guarantee_Tenant" UNIQUE ("TenantId", "GuaranteeId"),
  CONSTRAINT "UQ_Guarantee_CollateralId" UNIQUE ("TenantId", "CollateralId"),
  CONSTRAINT "CK_Guarantee_1" CHECK ("AmountMode" <> 'SPECIFIED' OR ("Amount" IS NOT NULL AND "CurrencyId" IS NOT NULL)),
  CONSTRAINT "CK_Guarantee_2" CHECK ("AmountMode" <> 'UNSPECIFIED' OR ("Amount" IS NULL AND "CurrencyId" IS NULL)),
  CONSTRAINT "CK_Guarantee_3" CHECK ("Amount" IS NULL OR "Amount" > 0),
  CONSTRAINT "CK_Guarantee_4" CHECK ("SignedOn" IS NULL OR "ValidTo" IS NULL OR "ValidTo" >= "SignedOn"),
  CONSTRAINT "CK_Guarantee_5" CHECK ("GuaranteeForm" <> 'JOINT_SEVERAL_PAYMENT_PERFORMANCE' OR "IsJointSeveral" = 1),
  CONSTRAINT "CK_Guarantee_GuaranteeForm" CHECK ("GuaranteeForm" IS NULL OR "GuaranteeForm" IN ('JOINT_SEVERAL_PAYMENT_PERFORMANCE', 'SIMPLE', 'OTHER')),
  CONSTRAINT "CK_Guarantee_AmountMode" CHECK ("AmountMode" IS NULL OR "AmountMode" IN ('SPECIFIED', 'UNSPECIFIED'))
);
CREATE TABLE "col"."PromissoryNote" (
  "TenantId" integer NOT NULL,
  "PromissoryNoteId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CollateralId" bigint NOT NULL,
  "NoteAmount" numeric(19,4) NOT NULL,
  "CurrencyId" integer NOT NULL,
  "IssuedOn" date NOT NULL,
  "DueKind" varchar(10) NOT NULL,
  "DueDate" date NULL,
  "RenewalCycle" varchar(10) NOT NULL,
  "LastRenewedOn" date NULL,
  "CustodyKind" varchar(10) NOT NULL,
  "NoteDocumentId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("PromissoryNoteId"),
  CONSTRAINT "UQ_PromissoryNote_Tenant" UNIQUE ("TenantId", "PromissoryNoteId"),
  CONSTRAINT "UQ_PromissoryNote_CollateralId" UNIQUE ("TenantId", "CollateralId"),
  CONSTRAINT "CK_PromissoryNote_1" CHECK ("NoteAmount" > 0),
  CONSTRAINT "CK_PromissoryNote_2" CHECK ("DueKind" <> 'FIXED_DATE' OR ("DueDate" IS NOT NULL AND "DueDate" >= "IssuedOn")),
  CONSTRAINT "CK_PromissoryNote_3" CHECK ("DueKind" <> 'ON_DEMAND' OR "DueDate" IS NULL),
  CONSTRAINT "CK_PromissoryNote_4" CHECK ("LastRenewedOn" IS NULL OR "LastRenewedOn" >= "IssuedOn"),
  CONSTRAINT "CK_PromissoryNote_5" CHECK ("RenewalCycle" <> 'NONE' OR "LastRenewedOn" IS NULL),
  CONSTRAINT "CK_PromissoryNote_DueKind" CHECK ("DueKind" IS NULL OR "DueKind" IN ('ON_DEMAND', 'FIXED_DATE')),
  CONSTRAINT "CK_PromissoryNote_RenewalCycle" CHECK ("RenewalCycle" IS NULL OR "RenewalCycle" IN ('NONE', 'ANNUAL')),
  CONSTRAINT "CK_PromissoryNote_CustodyKind" CHECK ("CustodyKind" IS NULL OR "CustodyKind" IN ('BANK', 'COMPANY', 'OTHER'))
);
CREATE TABLE "col"."PromissoryNoteSigner" (
  "TenantId" integer NOT NULL,
  "PromissoryNoteId" bigint NOT NULL,
  "PartyId" bigint NOT NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("TenantId", "PromissoryNoteId", "PartyId")
);
CREATE TABLE "col"."InsurancePolicyAssignment" (
  "TenantId" integer NOT NULL,
  "InsurancePolicyAssignmentId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CollateralId" bigint NOT NULL,
  "PolicyNo" varchar(60) NOT NULL,
  "InsurerName" varchar(200) NOT NULL,
  "AssignedToInstitutionId" bigint NOT NULL,
  "CoverageBasis" varchar(12) NOT NULL,
  "CoveragePct" numeric(9,6) NULL,
  "CoverageAmount" numeric(19,4) NULL,
  "SumInsured" numeric(19,4) NOT NULL,
  "CurrencyId" integer NOT NULL,
  "PolicyStart" date NULL,
  "PolicyExpiry" date NOT NULL,
  "AssignmentDate" date NULL,
  "PolicyDocumentId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("InsurancePolicyAssignmentId"),
  CONSTRAINT "UQ_InsurancePolicyAssignment_Tenant" UNIQUE ("TenantId", "InsurancePolicyAssignmentId"),
  CONSTRAINT "UQ_InsurancePolicyAssignment_CollateralId_PolicyNo" UNIQUE ("TenantId", "CollateralId", "PolicyNo"),
  CONSTRAINT "CK_InsurancePolicyAssignment_1" CHECK ("SumInsured" > 0),
  CONSTRAINT "CK_InsurancePolicyAssignment_2" CHECK ("PolicyStart" IS NULL OR "PolicyExpiry" >= "PolicyStart"),
  CONSTRAINT "CK_InsurancePolicyAssignment_3" CHECK ("CoverageBasis" <> 'PCT_OF_LIMIT' OR ("CoveragePct" IS NOT NULL AND "CoveragePct" > 0 AND "CoverageAmount" IS NULL)),
  CONSTRAINT "CK_InsurancePolicyAssignment_4" CHECK ("CoverageBasis" <> 'FIXED_AMOUNT' OR ("CoverageAmount" IS NOT NULL AND "CoverageAmount" > 0 AND "CoveragePct" IS NULL)),
  CONSTRAINT "CK_InsurancePolicyAssignment_5" CHECK ("CoverageBasis" <> 'FULL_LIMITS' OR ("CoveragePct" IS NULL AND "CoverageAmount" IS NULL)),
  CONSTRAINT "CK_InsurancePolicyAssignment_CoverageBasis" CHECK ("CoverageBasis" IS NULL OR "CoverageBasis" IN ('PCT_OF_LIMIT', 'FIXED_AMOUNT', 'FULL_LIMITS'))
);
CREATE TABLE "col"."ValuationSchedule" (
  "TenantId" integer NOT NULL,
  "ValuationScheduleId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CollateralId" bigint NOT NULL,
  "PhaseNo" integer NOT NULL,
  "FromYear" integer NOT NULL,
  "ToYear" integer NULL,
  "RequiredValuerCount" integer NOT NULL,
  "FrequencyMonths" integer NOT NULL,
  "ReferenceDate" date NOT NULL,
  "LastValuationOn" date NULL,
  "LastValuationAmount" numeric(19,4) NULL,
  "CurrencyId" integer NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("ValuationScheduleId"),
  CONSTRAINT "UQ_ValuationSchedule_Tenant" UNIQUE ("TenantId", "ValuationScheduleId"),
  CONSTRAINT "UQ_ValuationSchedule_CollateralId_PhaseNo" UNIQUE ("TenantId", "CollateralId", "PhaseNo"),
  CONSTRAINT "CK_ValuationSchedule_1" CHECK ("PhaseNo" >= 1),
  CONSTRAINT "CK_ValuationSchedule_2" CHECK ("FromYear" >= 1),
  CONSTRAINT "CK_ValuationSchedule_3" CHECK ("ToYear" IS NULL OR "ToYear" >= "FromYear"),
  CONSTRAINT "CK_ValuationSchedule_4" CHECK ("RequiredValuerCount" >= 1),
  CONSTRAINT "CK_ValuationSchedule_5" CHECK ("FrequencyMonths" >= 0),
  CONSTRAINT "CK_ValuationSchedule_6" CHECK ("LastValuationAmount" IS NULL OR ("LastValuationAmount" > 0 AND "LastValuationOn" IS NOT NULL AND "CurrencyId" IS NOT NULL)),
  CONSTRAINT "CK_ValuationSchedule_7" CHECK ("LastValuationOn" IS NULL OR "LastValuationAmount" IS NOT NULL)
);
CREATE TABLE "obl"."Obligation" (
  "TenantId" integer NOT NULL,
  "ObligationId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "FacilityId" bigint NOT NULL,
  "ObligationTypeId" integer NOT NULL,
  "TitleAr" varchar(300) NOT NULL,
  "TitleEn" varchar(300) NULL,
  "Phase" varchar(10) NOT NULL DEFAULT 'ONGOING',
  "ScopeLimitId" bigint NULL,
  "ScopeProductLineId" bigint NULL,
  "ClauseRef" varchar(100) NULL,
  "ClauseText" text NULL,
  "ConsequenceText" varchar(2000) NULL,
  "GraceDays" integer NULL,
  "CureDays" integer NULL,
  "ParamValue" numeric(19,6) NULL,
  "ParamUnit" varchar(13) NULL,
  "ParamCurrencyId" integer NULL,
  "TriggerField" varchar(100) NULL,
  "TriggerValues" text NULL,
  "CheckMode" varchar(10) NULL,
  "Status" varchar(10) NOT NULL DEFAULT 'ACTIVE',
  "ValidFrom" date NOT NULL,
  "ValidTo" date NULL,
  "FromRevision" integer NOT NULL DEFAULT 1,
  "ToRevision" integer NULL,
  "SupersedesId" bigint NULL,
  "SourceDocumentId" bigint NULL,
  "SourcePage" varchar(40) NULL,
  "ReadFromScan" smallint NOT NULL DEFAULT 0,
  CHECK ("ReadFromScan" IS NULL OR "ReadFromScan" IN (0,1)),
  "OriginalText" varchar(2000) NULL,
  "NoSourceReason" varchar(300) NULL,
  "Confidence" varchar(26) NOT NULL DEFAULT 'ENTERED_NO_DOCUMENT',
  "VerifiedBy" bigint NULL,
  "VerifiedOn" timestamp(3) NULL,
  "ConflictId" bigint NULL,
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("ObligationId"),
  CONSTRAINT "UQ_Obligation_Tenant" UNIQUE ("TenantId", "ObligationId"),
  CONSTRAINT "UQ_Obligation_PublicId" UNIQUE ("PublicId"),
  CONSTRAINT "CK_Obligation_1" CHECK ("ValidTo" IS NULL OR "ValidTo" >= "ValidFrom"),
  CONSTRAINT "CK_Obligation_2" CHECK ("GraceDays" IS NULL OR "GraceDays" >= 0),
  CONSTRAINT "CK_Obligation_3" CHECK ("CureDays" IS NULL OR "CureDays" >= 0),
  CONSTRAINT "CK_Obligation_4" CHECK (("ParamValue" IS NULL AND "ParamUnit" IS NULL) OR ("ParamValue" IS NOT NULL AND "ParamUnit" IS NOT NULL)),
  CONSTRAINT "CK_Obligation_5" CHECK ("ParamValue" IS NULL OR "ParamValue" >= 0),
  CONSTRAINT "CK_Obligation_6" CHECK ("ParamUnit" IS NULL OR "ParamUnit" <> 'AMOUNT' OR "ParamCurrencyId" IS NOT NULL),
  CONSTRAINT "CK_Obligation_7" CHECK ("ParamCurrencyId" IS NULL OR "ParamUnit" = 'AMOUNT'),
  CONSTRAINT "CK_Obligation_8" CHECK ("TriggerValues" IS NULL OR "TriggerField" IS NOT NULL),
  CONSTRAINT "CK_Obligation_9" CHECK ("ToRevision" IS NULL OR "ToRevision" >= "FromRevision"),
  CONSTRAINT "CK_Obligation_10" CHECK ("SourceDocumentId" IS NOT NULL AND "SourcePage" IS NOT NULL OR ("SourceDocumentId" IS NULL AND "Confidence" = 'ENTERED_NO_DOCUMENT')),
  CONSTRAINT "CK_Obligation_11" CHECK ("Confidence" <> 'CONFIRMED_AGAINST_ORIGINAL' OR ("VerifiedBy" IS NOT NULL AND "VerifiedOn" IS NOT NULL)),
  CONSTRAINT "CK_Obligation_Phase" CHECK ("Phase" IS NULL OR "Phase" IN ('PRECEDENT', 'ONGOING', 'SUBSEQUENT')),
  CONSTRAINT "CK_Obligation_ParamUnit" CHECK ("ParamUnit" IS NULL OR "ParamUnit" IN ('DAYS', 'BUSINESS_DAYS', 'MONTHS', 'PCT', 'AMOUNT')),
  CONSTRAINT "CK_Obligation_CheckMode" CHECK ("CheckMode" IS NULL OR "CheckMode" IN ('OFF', 'WARN', 'BLOCK')),
  CONSTRAINT "CK_Obligation_Status" CHECK ("Status" IS NULL OR "Status" IN ('ACTIVE', 'SUSPENDED', 'ENDED')),
  CONSTRAINT "CK_Obligation_Confidence" CHECK ("Confidence" IS NULL OR "Confidence" IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
CREATE TABLE "obl"."ObligationCompany" (
  "TenantId" integer NOT NULL,
  "ObligationId" bigint NOT NULL,
  "CompanyId" bigint NOT NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("TenantId", "ObligationId", "CompanyId")
);
CREATE TABLE "obl"."ReportingObligation" (
  "TenantId" integer NOT NULL,
  "ReportingObligationId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ObligationId" bigint NOT NULL,
  "Frequency" varchar(11) NOT NULL,
  "AnchorKind" varchar(21) NOT NULL,
  "OffsetValue" integer NULL,
  "OffsetUnit" varchar(13) NOT NULL DEFAULT 'CALENDAR_DAYS',
  "FixedDueDate" date NULL,
  "Direction" varchar(10) NOT NULL,
  "DocumentBasis" varchar(14) NOT NULL,
  "StatementScope" varchar(12) NULL,
  "SubmissionChannelId" integer NULL,
  "ChannelNote" varchar(300) NULL,
  "AlertLeadDays" varchar(40) NULL DEFAULT '30,14,7,3,1',
  "FirstPeriodEnd" date NULL,
  "HorizonMonths" integer NULL DEFAULT 24,
  "ExpectsEvidence" smallint NOT NULL,
  CHECK ("ExpectsEvidence" IS NULL OR "ExpectsEvidence" IN (0,1)),
  "FromRevision" integer NOT NULL DEFAULT 1,
  "ToRevision" integer NULL,
  "SupersedesId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("ReportingObligationId"),
  CONSTRAINT "UQ_ReportingObligation_Tenant" UNIQUE ("TenantId", "ReportingObligationId"),
  CONSTRAINT "CK_ReportingObligation_1" CHECK ("AnchorKind" <> 'FIXED_DATE' OR ("FixedDueDate" IS NOT NULL AND "OffsetValue" IS NULL)),
  CONSTRAINT "CK_ReportingObligation_2" CHECK ("AnchorKind" = 'FIXED_DATE' OR ("FixedDueDate" IS NULL AND "OffsetValue" IS NOT NULL)),
  CONSTRAINT "CK_ReportingObligation_3" CHECK ("OffsetValue" IS NULL OR "OffsetValue" >= 0),
  CONSTRAINT "CK_ReportingObligation_4" CHECK ("HorizonMonths" IS NULL OR "HorizonMonths" > 0),
  CONSTRAINT "CK_ReportingObligation_5" CHECK ("Frequency" <> 'EVENT_BASED' OR "AnchorKind" IN ('BEFORE_EVENT','AFTER_EVENT')),
  CONSTRAINT "CK_ReportingObligation_6" CHECK ("AnchorKind" NOT IN ('BEFORE_EVENT','AFTER_EVENT') OR "Frequency" = 'EVENT_BASED'),
  CONSTRAINT "CK_ReportingObligation_7" CHECK ("Frequency" <> 'ON_DEMAND' OR "AnchorKind" = 'ON_DEMAND_REQUEST'),
  CONSTRAINT "CK_ReportingObligation_8" CHECK ("AnchorKind" <> 'ON_DEMAND_REQUEST' OR "Frequency" = 'ON_DEMAND'),
  CONSTRAINT "CK_ReportingObligation_9" CHECK ("AlertLeadDays" IS NULL OR "AlertLeadDays" NOT LIKE '%[^0-9,]%'),
  CONSTRAINT "CK_ReportingObligation_10" CHECK ("ToRevision" IS NULL OR "ToRevision" >= "FromRevision"),
  CONSTRAINT "CK_ReportingObligation_Frequency" CHECK ("Frequency" IS NULL OR "Frequency" IN ('ANNUAL', 'SEMIANNUAL', 'QUARTERLY', 'MONTHLY', 'ONE_TIME', 'EVENT_BASED', 'ON_DEMAND')),
  CONSTRAINT "CK_ReportingObligation_AnchorKind" CHECK ("AnchorKind" IS NULL OR "AnchorKind" IN ('AFTER_PERIOD_END', 'AFTER_FISCAL_YEAR_END', 'BEFORE_EVENT', 'AFTER_EVENT', 'ON_DEMAND_REQUEST', 'FIXED_DATE')),
  CONSTRAINT "CK_ReportingObligation_OffsetUnit" CHECK ("OffsetUnit" IS NULL OR "OffsetUnit" IN ('CALENDAR_DAYS', 'BUSINESS_DAYS', 'MONTHS')),
  CONSTRAINT "CK_ReportingObligation_Direction" CHECK ("Direction" IS NULL OR "Direction" IN ('WE_SUBMIT', 'WE_RESPOND')),
  CONSTRAINT "CK_ReportingObligation_DocumentBasis" CHECK ("DocumentBasis" IS NULL OR "DocumentBasis" IN ('AUDITED', 'INTERNAL', 'ANY', 'NOT_APPLICABLE')),
  CONSTRAINT "CK_ReportingObligation_StatementScope" CHECK ("StatementScope" IS NULL OR "StatementScope" IN ('STANDALONE', 'CONSOLIDATED', 'ANY'))
);
CREATE TABLE "obl"."ReportingInstance" (
  "TenantId" integer NOT NULL,
  "ReportingInstanceId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ReportingObligationId" bigint NOT NULL,
  "PeriodStart" date NULL,
  "PeriodEnd" date NULL,
  "EventDate" date NULL,
  "DueDate" date NOT NULL,
  "DueDateOverrideReason" varchar(500) NULL,
  "Status" varchar(14) NOT NULL DEFAULT 'SCHEDULED',
  "StatusReason" varchar(500) NULL,
  "SubmittedOn" date NULL,
  "SubmissionChannelUsedId" integer NULL,
  "SubmissionRef" varchar(100) NULL,
  "EvidenceDocumentId" bigint NULL,
  "ReportedAmount" numeric(19,4) NULL,
  "CurrencyId" integer NULL,
  "GeneratedBy" varchar(12) NOT NULL DEFAULT 'JOB',
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("ReportingInstanceId"),
  CONSTRAINT "UQ_ReportingInstance_Tenant" UNIQUE ("TenantId", "ReportingInstanceId"),
  CONSTRAINT "UQ_ReportingInstance_PublicId" UNIQUE ("PublicId"),
  CONSTRAINT "CK_ReportingInstance_1" CHECK ("PeriodStart" IS NULL OR ("PeriodEnd" IS NOT NULL AND "PeriodEnd" >= "PeriodStart")),
  CONSTRAINT "CK_ReportingInstance_2" CHECK ("GeneratedBy" <> 'MANUAL_EVENT' OR "EventDate" IS NOT NULL),
  CONSTRAINT "CK_ReportingInstance_3" CHECK ("Status" <> 'SUBMITTED' OR "SubmittedOn" IS NOT NULL),
  CONSTRAINT "CK_ReportingInstance_4" CHECK ("Status" = 'SUBMITTED' OR ("SubmittedOn" IS NULL AND "SubmissionChannelUsedId" IS NULL AND "SubmissionRef" IS NULL)),
  CONSTRAINT "CK_ReportingInstance_5" CHECK ("Status" NOT IN ('NOT_APPLICABLE','CANCELLED') OR "StatusReason" IS NOT NULL),
  CONSTRAINT "CK_ReportingInstance_6" CHECK ("ReportedAmount" IS NULL OR "CurrencyId" IS NOT NULL),
  CONSTRAINT "CK_ReportingInstance_7" CHECK ("CurrencyId" IS NULL OR "ReportedAmount" IS NOT NULL),
  CONSTRAINT "CK_ReportingInstance_Status" CHECK ("Status" IS NULL OR "Status" IN ('SCHEDULED', 'SUBMITTED', 'WAIVED', 'NOT_APPLICABLE', 'CANCELLED')),
  CONSTRAINT "CK_ReportingInstance_GeneratedBy" CHECK ("GeneratedBy" IS NULL OR "GeneratedBy" IN ('JOB', 'MANUAL_EVENT'))
);
CREATE TABLE "obl"."Covenant" (
  "TenantId" integer NOT NULL,
  "CovenantId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ObligationId" bigint NOT NULL,
  "MeasureKind" varchar(18) NOT NULL,
  "FormulaId" bigint NULL,
  "Operator" varchar(10) NULL,
  "ThresholdState" varchar(26) NOT NULL,
  "ThresholdValue" numeric(19,6) NULL,
  "ThresholdUnit" varchar(10) NULL,
  "CurrencyId" integer NULL,
  "TestFrequency" varchar(11) NOT NULL,
  "AggregationMode" varchar(14) NULL,
  "AnnualWindowBasis" varchar(13) NULL,
  "StatementBasis" varchar(12) NULL,
  "RequiredAssurance" varchar(14) NULL,
  "RevenueBasisRule" varchar(15) NULL,
  "AccountScopeKind" varchar(28) NULL,
  "TestedCompanyId" bigint NOT NULL,
  "SubmissionLagDays" integer NULL,
  "FirstTestPeriodEnd" date NOT NULL,
  "EarlyWarningPct" numeric(9,6) NULL,
  "ValidFrom" date NOT NULL,
  "ValidTo" date NULL,
  "FromRevision" integer NOT NULL DEFAULT 1,
  "ToRevision" integer NULL,
  "SupersedesId" bigint NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CovenantId"),
  CONSTRAINT "UQ_Covenant_Tenant" UNIQUE ("TenantId", "CovenantId"),
  CONSTRAINT "CK_Covenant_1" CHECK ("MeasureKind" NOT IN ('RATIO','AMOUNT','PERCENT_OF_REVENUE') OR "FormulaId" IS NOT NULL),
  CONSTRAINT "CK_Covenant_2" CHECK ("MeasureKind" <> 'NONE' OR ("FormulaId" IS NULL AND "Operator" IS NULL AND "ThresholdValue" IS NULL AND "ThresholdState" <> 'SET')),
  CONSTRAINT "CK_Covenant_3" CHECK ("ThresholdState" <> 'SET' OR ("Operator" IS NOT NULL AND "ThresholdValue" IS NOT NULL)),
  CONSTRAINT "CK_Covenant_4" CHECK ("ThresholdState" = 'SET' OR "ThresholdValue" IS NULL),
  CONSTRAINT "CK_Covenant_5" CHECK ("ThresholdState" <> 'SET' OR "ThresholdUnit" IS NULL OR "ThresholdUnit" <> 'AMOUNT' OR "CurrencyId" IS NOT NULL),
  CONSTRAINT "CK_Covenant_6" CHECK ("CurrencyId" IS NULL OR "ThresholdUnit" = 'AMOUNT'),
  CONSTRAINT "CK_Covenant_7" CHECK ("RevenueBasisRule" IS NULL OR "MeasureKind" = 'PERCENT_OF_REVENUE'),
  CONSTRAINT "CK_Covenant_8" CHECK ("SubmissionLagDays" IS NULL OR "SubmissionLagDays" >= 0),
  CONSTRAINT "CK_Covenant_9" CHECK ("EarlyWarningPct" IS NULL OR ("EarlyWarningPct" >= 0 AND "EarlyWarningPct" <= 100)),
  CONSTRAINT "CK_Covenant_10" CHECK ("ValidTo" IS NULL OR "ValidTo" >= "ValidFrom"),
  CONSTRAINT "CK_Covenant_11" CHECK ("ToRevision" IS NULL OR "ToRevision" >= "FromRevision"),
  CONSTRAINT "CK_Covenant_MeasureKind" CHECK ("MeasureKind" IS NULL OR "MeasureKind" IN ('RATIO', 'AMOUNT', 'PERCENT_OF_REVENUE', 'AVERAGE_BALANCE', 'FLOW_VOLUME', 'NONE')),
  CONSTRAINT "CK_Covenant_Operator" CHECK ("Operator" IS NULL OR "Operator" IN ('GE', 'LE', 'GT', 'LT', 'EQ')),
  CONSTRAINT "CK_Covenant_ThresholdState" CHECK ("ThresholdState" IS NULL OR "ThresholdState" IN ('SET', 'NOT_SPECIFIED_IN_AGREEMENT', 'TO_BE_DETERMINED')),
  CONSTRAINT "CK_Covenant_ThresholdUnit" CHECK ("ThresholdUnit" IS NULL OR "ThresholdUnit" IN ('RATIO', 'AMOUNT', 'PERCENT')),
  CONSTRAINT "CK_Covenant_TestFrequency" CHECK ("TestFrequency" IS NULL OR "TestFrequency" IN ('MONTHLY', 'QUARTERLY', 'SEMIANNUAL', 'ANNUAL', 'ROLLING_12M')),
  CONSTRAINT "CK_Covenant_AggregationMode" CHECK ("AggregationMode" IS NULL OR "AggregationMode" IN ('POINT_IN_TIME', 'PERIOD_AVERAGE', 'EACH_MONTH_MIN', 'PERIOD_SUM')),
  CONSTRAINT "CK_Covenant_AnnualWindowBasis" CHECK ("AnnualWindowBasis" IS NULL OR "AnnualWindowBasis" IN ('FISCAL_YEAR', 'CALENDAR_YEAR', 'FACILITY_YEAR')),
  CONSTRAINT "CK_Covenant_StatementBasis" CHECK ("StatementBasis" IS NULL OR "StatementBasis" IN ('STANDALONE', 'CONSOLIDATED')),
  CONSTRAINT "CK_Covenant_RequiredAssurance" CHECK ("RequiredAssurance" IS NULL OR "RequiredAssurance" IN ('AUDITED_ONLY', 'PREFER_AUDITED', 'ANY')),
  CONSTRAINT "CK_Covenant_RevenueBasisRule" CHECK ("RevenueBasisRule" IS NULL OR "RevenueBasisRule" IN ('SAME_PERIOD', 'PRIOR_YEAR', 'MANUAL_ESTIMATE')),
  CONSTRAINT "CK_Covenant_AccountScopeKind" CHECK ("AccountScopeKind" IS NULL OR "AccountScopeKind" IN ('ALL_COMPANY_ACCOUNTS_AT_BANK', 'SELECTED_ACCOUNTS', 'GROUP_ACCOUNTS'))
);
CREATE TABLE "obl"."CovenantAccount" (
  "TenantId" integer NOT NULL,
  "CovenantId" bigint NOT NULL,
  "BankAccountId" bigint NOT NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("TenantId", "CovenantId", "BankAccountId")
);
CREATE TABLE "obl"."CovenantTest" (
  "TenantId" integer NOT NULL,
  "CovenantTestId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CovenantId" bigint NOT NULL,
  "PeriodStart" date NOT NULL,
  "PeriodEnd" date NOT NULL,
  "DueDate" date NOT NULL,
  "EvaluationNo" integer NOT NULL DEFAULT 1,
  "State" varchar(12) NOT NULL DEFAULT 'SCHEDULED',
  "Result" varchar(25) NULL,
  "Method" varchar(13) NOT NULL,
  "ActualValue" numeric(19,6) NULL,
  "ThresholdApplied" numeric(19,6) NULL,
  "OperatorApplied" varchar(10) NULL,
  "Headroom" numeric(19,6) NULL,
  "HeadroomPct" numeric(19,6) NULL,
  "InputsSnapshot" text NULL,
  "FormulaVersion" integer NULL,
  "EvaluatedAt" timestamp(3) NULL,
  "EvaluatedBy" bigint NULL,
  "EvidenceDocumentId" bigint NULL,
  "ReviewNote" varchar(1000) NULL,
  "ReviewedBy" bigint NULL,
  "ReviewedOn" timestamp(3) NULL,
  "NextReviewOn" date NULL,
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CovenantTestId"),
  CONSTRAINT "UQ_CovenantTest_Tenant" UNIQUE ("TenantId", "CovenantTestId"),
  CONSTRAINT "UQ_CovenantTest_PublicId" UNIQUE ("PublicId"),
  CONSTRAINT "UQ_CovenantTest_CovenantId_PeriodEnd_EvaluationNo" UNIQUE ("TenantId", "CovenantId", "PeriodEnd", "EvaluationNo"),
  CONSTRAINT "CK_CovenantTest_1" CHECK ("EvaluationNo" >= 1),
  CONSTRAINT "CK_CovenantTest_2" CHECK ("PeriodEnd" >= "PeriodStart"),
  CONSTRAINT "CK_CovenantTest_3" CHECK ("DueDate" >= "PeriodEnd"),
  CONSTRAINT "CK_CovenantTest_4" CHECK ("State" <> 'SCHEDULED' OR ("Result" IS NULL AND "EvaluatedAt" IS NULL)),
  CONSTRAINT "CK_CovenantTest_5" CHECK ("State" NOT IN ('EVALUATED','REVIEWED') OR ("Result" IS NOT NULL AND "EvaluatedAt" IS NOT NULL AND "InputsSnapshot" IS NOT NULL)),
  CONSTRAINT "CK_CovenantTest_6" CHECK ("State" <> 'REVIEWED' OR ("ReviewedBy" IS NOT NULL AND "ReviewedOn" IS NOT NULL)),
  CONSTRAINT "CK_CovenantTest_7" CHECK ("Result" NOT IN ('COMPLIANT','WARNING','BREACH') OR ("ActualValue" IS NOT NULL AND "ThresholdApplied" IS NOT NULL AND "OperatorApplied" IS NOT NULL)),
  CONSTRAINT "CK_CovenantTest_8" CHECK ("Result" <> 'NOT_ASSESSED_NO_THRESHOLD' OR "ThresholdApplied" IS NULL),
  CONSTRAINT "CK_CovenantTest_9" CHECK ("ThresholdApplied" IS NULL OR "OperatorApplied" IS NOT NULL),
  CONSTRAINT "CK_CovenantTest_10" CHECK ("Headroom" IS NULL OR ("ActualValue" IS NOT NULL AND "ThresholdApplied" IS NOT NULL)),
  CONSTRAINT "CK_CovenantTest_11" CHECK ("HeadroomPct" IS NULL OR "Headroom" IS NOT NULL),
  CONSTRAINT "CK_CovenantTest_12" CHECK ("Result" NOT IN ('MANUAL_COMPLIANT','MANUAL_NON_COMPLIANT','UNDER_REVIEW') OR "Method" = 'MANUAL_STATUS'),
  CONSTRAINT "CK_CovenantTest_13" CHECK ("Method" <> 'MANUAL_STATUS' OR "Result" IS NULL OR "Result" IN ('MANUAL_COMPLIANT','MANUAL_NON_COMPLIANT','UNDER_REVIEW')),
  CONSTRAINT "CK_CovenantTest_14" CHECK ("FormulaVersion" IS NULL OR "FormulaVersion" >= 1),
  CONSTRAINT "CK_CovenantTest_State" CHECK ("State" IS NULL OR "State" IN ('SCHEDULED', 'PENDING_DATA', 'EVALUATED', 'REVIEWED')),
  CONSTRAINT "CK_CovenantTest_Result" CHECK ("Result" IS NULL OR "Result" IN ('COMPLIANT', 'WARNING', 'BREACH', 'MISSING_DATA', 'NOT_ASSESSED_NO_THRESHOLD', 'NOT_COMPARABLE', 'MANUAL_COMPLIANT', 'MANUAL_NON_COMPLIANT', 'UNDER_REVIEW')),
  CONSTRAINT "CK_CovenantTest_Method" CHECK ("Method" IS NULL OR "Method" IN ('AUTO', 'MANUAL_VALUE', 'MANUAL_STATUS')),
  CONSTRAINT "CK_CovenantTest_OperatorApplied" CHECK ("OperatorApplied" IS NULL OR "OperatorApplied" IN ('GE', 'LE', 'GT', 'LT', 'EQ'))
);
CREATE TABLE "obl"."ObligationBreach" (
  "TenantId" integer NOT NULL,
  "ObligationBreachId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ObligationId" bigint NOT NULL,
  "Kind" varchar(21) NOT NULL,
  "CovenantTestId" bigint NULL,
  "ReportingInstanceId" bigint NULL,
  "DetectedOn" date NOT NULL,
  "Description" varchar(2000) NULL,
  "Status" varchar(16) NOT NULL DEFAULT 'OPEN',
  "CureDeadline" date NULL,
  "BankNotifiedOn" date NULL,
  "WaiverRef" varchar(100) NULL,
  "WaiverDate" date NULL,
  "WaiverBankContactId" bigint NULL,
  "WaiverConditions" varchar(2000) NULL,
  "WaiverValidUntil" date NULL,
  "WaiverDocumentId" bigint NULL,
  "ConsequenceApplied" varchar(1000) NULL,
  "ResolvedOn" date NULL,
  "NeedsReview" smallint NOT NULL DEFAULT 0,
  CHECK ("NeedsReview" IS NULL OR "NeedsReview" IN (0,1)),
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("ObligationBreachId"),
  CONSTRAINT "UQ_ObligationBreach_Tenant" UNIQUE ("TenantId", "ObligationBreachId"),
  CONSTRAINT "UQ_ObligationBreach_PublicId" UNIQUE ("PublicId"),
  CONSTRAINT "CK_ObligationBreach_1" CHECK ("CovenantTestId" IS NULL OR "Kind" = 'COVENANT_BREACH'),
  CONSTRAINT "CK_ObligationBreach_2" CHECK ("ReportingInstanceId" IS NULL OR "Kind" = 'LATE_REPORT'),
  CONSTRAINT "CK_ObligationBreach_3" CHECK ("CureDeadline" IS NULL OR "CureDeadline" >= "DetectedOn"),
  CONSTRAINT "CK_ObligationBreach_4" CHECK ("Status" <> 'IN_CURE' OR "CureDeadline" IS NOT NULL),
  CONSTRAINT "CK_ObligationBreach_5" CHECK ("Status" NOT IN ('CURED','WAIVED','CLOSED_NO_ACTION') OR "ResolvedOn" IS NOT NULL),
  CONSTRAINT "CK_ObligationBreach_6" CHECK ("Status" IN ('CURED','WAIVED','CLOSED_NO_ACTION') OR "ResolvedOn" IS NULL),
  CONSTRAINT "CK_ObligationBreach_7" CHECK ("ResolvedOn" IS NULL OR "ResolvedOn" >= "DetectedOn"),
  CONSTRAINT "CK_ObligationBreach_8" CHECK ("Status" <> 'WAIVED' OR ("WaiverRef" IS NOT NULL AND "WaiverDate" IS NOT NULL AND "WaiverBankContactId" IS NOT NULL)),
  CONSTRAINT "CK_ObligationBreach_9" CHECK ("Status" = 'WAIVED' OR ("WaiverRef" IS NULL AND "WaiverDate" IS NULL AND "WaiverBankContactId" IS NULL AND "WaiverConditions" IS NULL AND "WaiverValidUntil" IS NULL AND "WaiverDocumentId" IS NULL)),
  CONSTRAINT "CK_ObligationBreach_10" CHECK ("WaiverValidUntil" IS NULL OR "WaiverDate" IS NULL OR "WaiverValidUntil" >= "WaiverDate"),
  CONSTRAINT "CK_ObligationBreach_Kind" CHECK ("Kind" IS NULL OR "Kind" IN ('COVENANT_BREACH', 'LATE_REPORT', 'RESTRICTION_VIOLATION', 'OTHER')),
  CONSTRAINT "CK_ObligationBreach_Status" CHECK ("Status" IS NULL OR "Status" IN ('OPEN', 'IN_CURE', 'CURED', 'WAIVED', 'CLOSED_NO_ACTION'))
);
CREATE TABLE "fin"."LineCatalogItem" (
  "TenantId" integer NOT NULL,
  "LineCatalogItemId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Code" varchar(80) NOT NULL,
  "NameAr" varchar(200) NOT NULL,
  "NameEn" varchar(200) NULL,
  "Description" varchar(500) NULL,
  "IsActive" smallint NOT NULL DEFAULT 1,
  CHECK ("IsActive" IS NULL OR "IsActive" IN (0,1)),
  "IsSystem" smallint NOT NULL DEFAULT 0,
  CHECK ("IsSystem" IS NULL OR "IsSystem" IN (0,1)),
  "IsLocked" smallint NOT NULL DEFAULT 0,
  CHECK ("IsLocked" IS NULL OR "IsLocked" IN (0,1)),
  "SortOrder" integer NOT NULL DEFAULT 0,
  "SeedKey" varchar(80) NULL,
  "ExternalCode" varchar(80) NULL,
  "Section" varchar(12) NOT NULL,
  "IsTotal" smallint NOT NULL DEFAULT 0,
  CHECK ("IsTotal" IS NULL OR "IsTotal" IN (0,1)),
  "TotalFormula" varchar(500) NULL,
  "IsRequired" smallint NOT NULL DEFAULT 0,
  CHECK ("IsRequired" IS NULL OR "IsRequired" IN (0,1)),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("LineCatalogItemId"),
  CONSTRAINT "UQ_LineCatalogItem_Tenant" UNIQUE ("TenantId", "LineCatalogItemId"),
  CONSTRAINT "UQ_LineCatalogItem_Code" UNIQUE ("TenantId", "Code"),
  CONSTRAINT "CK_LineCatalogItem_1" CHECK ("IsTotal" = 0 OR "TotalFormula" IS NOT NULL),
  CONSTRAINT "CK_LineCatalogItem_2" CHECK ("IsTotal" = 1 OR "TotalFormula" IS NULL),
  CONSTRAINT "CK_LineCatalogItem_3" CHECK ("NameEn" IS NOT NULL),
  CONSTRAINT "CK_LineCatalogItem_4" CHECK ("Code" NOT LIKE '%[^A-Z0-9_]%' AND "Code" NOT LIKE '[0-9_]%'),
  CONSTRAINT "CK_LineCatalogItem_5" CHECK ("IsLocked" = 0 OR ("IsSystem" = 1 AND "IsActive" = 1)),
  CONSTRAINT "CK_LineCatalogItem_Section" CHECK ("Section" IS NULL OR "Section" IN ('BS_ASSET', 'BS_LIABILITY', 'BS_EQUITY', 'IS', 'CF'))
);
CREATE TABLE "fin"."LineCatalogItemAlias" (
  "TenantId" integer NOT NULL,
  "LineCatalogItemAliasId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "LineCatalogItemId" integer NOT NULL,
  "Alias" varchar(200) NOT NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("LineCatalogItemAliasId"),
  CONSTRAINT "UQ_LineCatalogItemAlias_Tenant" UNIQUE ("TenantId", "LineCatalogItemAliasId"),
  CONSTRAINT "UQ_LineCatalogItemAlias_Alias" UNIQUE ("TenantId", "Alias"),
  CONSTRAINT "CK_LineCatalogItemAlias_1" CHECK ("Alias" <> '')
);
CREATE TABLE "fin"."FinancialStatement" (
  "TenantId" integer NOT NULL,
  "FinancialStatementId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "CompanyId" bigint NOT NULL,
  "PeriodType" varchar(10) NOT NULL,
  "PeriodStart" date NULL,
  "PeriodEnd" date NOT NULL,
  "FiscalYear" integer NOT NULL,
  "Basis" varchar(12) NOT NULL,
  "Assurance" varchar(10) NOT NULL,
  "CurrencyId" integer NOT NULL,
  "UnitScale" integer NOT NULL DEFAULT 1,
  "AccountingStandard" varchar(100) NULL,
  "VersionNo" integer NOT NULL DEFAULT 1,
  "VersionReason" varchar(10) NOT NULL DEFAULT 'ORIGINAL',
  "SupersedesId" bigint NULL,
  "Status" varchar(10) NOT NULL DEFAULT 'DRAFT',
  "EntryMethod" varchar(10) NOT NULL,
  "BalanceReason" varchar(500) NULL,
  "SourceDocumentId" bigint NULL,
  "PreparedBy" bigint NULL,
  "PreparedOn" timestamp(3) NULL,
  "ApprovedBy" bigint NULL,
  "ApprovedOn" timestamp(3) NULL,
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("FinancialStatementId"),
  CONSTRAINT "UQ_FinancialStatement_Tenant" UNIQUE ("TenantId", "FinancialStatementId"),
