  "NumberSeq" integer NULL,
  "RequestTypeId" integer NOT NULL,
  "TemplateId" integer NOT NULL,
  "CompanyId" bigint NOT NULL,
  "DepartmentId" bigint NULL,
  "RequesterUserId" bigint NOT NULL,
  "CreatedByUserId" bigint NOT NULL,
  "SubmittedByUserId" bigint NULL,
  "Title" varchar(200) NULL,
  "Status" varchar(10) NOT NULL DEFAULT 'DRAFT',
  "CurrentStageId" integer NULL,
  "CurrentStageInstanceId" bigint NULL,
  "ExternalPhaseId" integer NOT NULL,
  "SubStatusKey" varchar(40) NULL,
  "AssigneeUserId" bigint NULL,
  "QueueEnteredAt" timestamp(3) NULL,
  "ClaimedAt" timestamp(3) NULL,
  "DueAt" timestamp(3) NULL,
