CREATE TABLE "wfl"."RequestStageInstance" (
  "TenantId" integer NOT NULL,
  "RequestStageInstanceId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "RequestId" bigint NOT NULL,
  "StageId" integer NOT NULL,
  "CycleNo" integer NOT NULL DEFAULT 1,
  "Status" varchar(17) NOT NULL,
  "EnteredAt" timestamp(3) NOT NULL,
  "QueuedAt" timestamp(3) NULL,
  "ClaimedAt" timestamp(3) NULL,
  "ExitedAt" timestamp(3) NULL,
  "ExitAction" varchar(10) NULL,
  "AssigneeUserId" bigint NULL,
  "DueAt" timestamp(3) NULL,
  "ClaimDueAt" timestamp(3) NULL,
  "SlaPausedSeconds" integer NOT NULL DEFAULT 0,
  "SlaState" varchar(10) NOT NULL DEFAULT 'NONE',
  "SlaMet" smallint NULL,
  CHECK ("SlaMet" IS NULL OR "SlaMet" IN (0,1)),
  "ReleaseCount" integer NOT NULL DEFAULT 0,
  "ReassignCount" integer NOT NULL DEFAULT 0,
  "ResumeStageId" integer NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("RequestStageInstanceId"),
  CONSTRAINT "UQ_RequestStageInstance_Tenant" UNIQUE ("TenantId", "RequestStageInstanceId"),
  CONSTRAINT "UQ_RequestStageInstance_Scope_RequestId" UNIQUE ("TenantId", "RequestId", "RequestStageInstanceId"),
  CONSTRAINT "CK_RequestStageInstance_1" CHECK (("ExitedAt" IS NULL AND "ExitAction" IS NULL AND "Status" IN ('QUEUED','CLAIMED','AWAITING_APPROVAL')) OR ("ExitedAt" IS NOT NULL AND "ExitAction" IS NOT NULL AND "Status" IN ('DONE','RETURNED','REJECTED','CANCELLED'))),
  CONSTRAINT "CK_RequestStageInstance_2" CHECK ("Status" <> 'RETURNED' OR "ExitAction" = 'RETURN'),
  CONSTRAINT "CK_RequestStageInstance_3" CHECK ("Status" <> 'REJECTED' OR "ExitAction" = 'REJECT'),
  CONSTRAINT "CK_RequestStageInstance_4" CHECK ("Status" <> 'CANCELLED' OR "ExitAction" = 'CANCEL'),
  CONSTRAINT "CK_RequestStageInstance_5" CHECK ("Status" <> 'QUEUED' OR "AssigneeUserId" IS NULL),
  CONSTRAINT "CK_RequestStageInstance_6" CHECK ("Status" <> 'CLAIMED' OR "AssigneeUserId" IS NOT NULL),
  CONSTRAINT "CK_RequestStageInstance_7" CHECK ("ClaimedAt" IS NULL OR "QueuedAt" IS NOT NULL),
  CONSTRAINT "CK_RequestStageInstance_8" CHECK ("ExitedAt" IS NULL OR "ExitedAt" >= "EnteredAt"),
  CONSTRAINT "CK_RequestStageInstance_9" CHECK ("QueuedAt" IS NULL OR "QueuedAt" >= "EnteredAt"),
  CONSTRAINT "CK_RequestStageInstance_10" CHECK ("ClaimedAt" IS NULL OR "QueuedAt" IS NULL OR "ClaimedAt" >= "QueuedAt"),
  CONSTRAINT "CK_RequestStageInstance_11" CHECK ("SlaPausedSeconds" >= 0 AND "ReleaseCount" >= 0 AND "ReassignCount" >= 0),
  CONSTRAINT "CK_RequestStageInstance_12" CHECK ("CycleNo" >= 1),
  CONSTRAINT "CK_RequestStageInstance_Status" CHECK ("Status" IS NULL OR "Status" IN ('QUEUED', 'CLAIMED', 'AWAITING_APPROVAL', 'DONE', 'RETURNED', 'REJECTED', 'CANCELLED')),
  CONSTRAINT "CK_RequestStageInstance_ExitAction" CHECK ("ExitAction" IS NULL OR "ExitAction" IN ('SUBMIT', 'APPROVE', 'COMPLETE', 'RETURN', 'REJECT', 'CANCEL', 'RESUBMIT')),
  CONSTRAINT "CK_RequestStageInstance_SlaState" CHECK ("SlaState" IS NULL OR "SlaState" IN ('ON_TRACK', 'AT_RISK', 'OVERDUE', 'PAUSED', 'NONE'))
);
