CREATE TABLE "wfl"."HookExecution" (
  "TenantId" integer NOT NULL,
  "HookExecutionId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "RequestId" bigint NOT NULL,
  "StageInstanceId" bigint NOT NULL,
